/* =========================================================
   ZOMBIE OUTBREAK — interface & atmosphere
   ========================================================= */
:root {
  --bg: #07090c;
  --bg-soft: #0d1116;
  --panel: rgba(10, 14, 18, 0.88);
  --panel-solid: #0c1015;
  --line: rgba(255, 255, 255, 0.12);
  --line-strong: rgba(255, 255, 255, 0.22);
  --text: #eef1f3;
  --muted: #8b98a5;
  --dim: #5d6a76;
  --red: #e5383b;
  --red-bright: #ff5252;
  --red-dark: #7d1416;
  --amber: #ffb703;
  --amber-soft: #ffd166;
  --green: #8ac926;
  --toxic: #9dff4d;
  --cyan: #4cc9f0;
  --font-display: "Arial Black", "Haettenschweiler", Impact, "Franklin Gothic Heavy", sans-serif;
  --font-ui: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  --font-mono: ui-monospace, "Cascadia Mono", "SF Mono", "Roboto Mono", Menlo, monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-ui);
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
  overscroll-behavior: none;
}

body { position: fixed; inset: 0; }
button { font-family: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--amber); outline-offset: 3px; }
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 5px;
  border: 1px solid var(--line-strong);
  border-bottom-color: rgba(255,255,255,0.35);
  border-radius: 3px;
  background: rgba(255,255,255,0.06);
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1;
  color: #dde4e8;
  box-shadow: 0 2px 0 rgba(0,0,0,0.4);
}

#app { position: relative; width: 100%; height: 100%; overflow: hidden; background: #07090c; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
body.playing.desktop #game { cursor: none; }

/* ============ global atmosphere ============ */
.fx-vignette {
  position: absolute; inset: 0; z-index: 5; pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 32%, rgba(2, 4, 6, 0.34) 72%, rgba(1, 2, 3, 0.82) 100%),
    linear-gradient(180deg, rgba(4, 7, 10, 0.4), transparent 18%, transparent 78%, rgba(2, 4, 6, 0.55));
}
.fx-scanlines {
  position: absolute; inset: 0; z-index: 6; pointer-events: none; opacity: 0.18;
  background: repeating-linear-gradient(0deg, rgba(255,255,255,0.03) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}
#damage-flash {
  position: absolute; inset: 0; z-index: 7; pointer-events: none; opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 35%, rgba(190, 18, 22, 0.55) 85%, rgba(120, 0, 4, 0.9) 100%);
  transition: opacity 0.1s linear;
  mix-blend-mode: screen;
}
#nuke-flash {
  position: absolute; inset: 0; z-index: 8; pointer-events: none; opacity: 0;
  background: radial-gradient(circle at 50% 50%, rgba(255,245,210,0.95), rgba(255,183,3,0.5) 40%, transparent 75%);
  transition: opacity 0.35s ease-out;
}
.hidden { display: none !important; }

/* ============ shared ============ */
.panel {
  position: relative;
  background: linear-gradient(160deg, rgba(17, 23, 29, 0.97), rgba(8, 11, 15, 0.97));
  border: 1px solid var(--line);
  box-shadow: 0 26px 80px rgba(0,0,0,0.65), inset 0 1px 0 rgba(255,255,255,0.05);
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 20px 100%, 0 calc(100% - 20px));
}
.panel::before {
  content: ""; position: absolute; left: 0; top: 0; width: 46px; height: 2px;
  background: var(--red); box-shadow: 0 0 14px rgba(229, 56, 59, 0.7);
}
.eyebrow {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.32em;
  color: var(--amber); text-transform: uppercase;
}
.eyebrow.center { justify-content: center; }
.eyebrow-line { display: inline-block; width: 26px; height: 1px; background: var(--amber); opacity: 0.6; }
.accent { color: var(--red-bright); }
.center { text-align: center; }
.bar { position: relative; overflow: hidden; background: rgba(255,255,255,0.08); border-radius: 1px; }
.bar-fill { height: 100%; width: 100%; transition: width 0.14s ease-out; }

/* ============ buttons ============ */
.btn {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  height: 46px; padding: 0 24px;
  font-family: var(--font-ui); font-weight: 800; font-size: 12px;
  letter-spacing: 0.2em; text-transform: uppercase; white-space: nowrap;
  border: 1px solid transparent;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  transition: transform 0.16s ease, background 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease, color 0.16s ease;
  overflow: hidden;
}
.btn:hover { transform: translateY(-2px); }
.btn:active { transform: translateY(0); }
.btn-primary {
  background: linear-gradient(180deg, #f04a4d, #c11f24);
  color: #fff; border-color: rgba(255,255,255,0.18);
  box-shadow: 0 10px 28px rgba(201, 24, 30, 0.35), inset 0 1px 0 rgba(255,255,255,0.3);
  text-shadow: 0 1px 2px rgba(0,0,0,0.35);
}
.btn-primary:hover { background: linear-gradient(180deg, #ff5b5e, #d42429); box-shadow: 0 14px 34px rgba(220, 30, 36, 0.5), inset 0 1px 0 rgba(255,255,255,0.3); }
.btn-primary .btn-arrow { font-size: 18px; line-height: 1; transform: translateY(-1px); transition: transform 0.16s ease; }
.btn-primary:hover .btn-arrow { transform: translate(3px, -1px); }
.btn-lg { height: 58px; padding: 0 34px; font-size: 14px; }
.btn-ghost {
  background: rgba(255,255,255,0.035); border-color: var(--line-strong); color: #dfe6ea;
}
.btn-ghost:hover { background: rgba(255,255,255,0.09); border-color: rgba(255,255,255,0.4); }
.btn-quiet { height: 38px; color: var(--dim); font-size: 10px; border-color: transparent; }
.btn-quiet:hover { color: var(--muted); background: rgba(255,255,255,0.03); }
.btn .btn-glint {
  position: absolute; top: 0; left: -60%; width: 40%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.25), transparent);
  transform: skewX(-20deg); animation: glint 4.5s ease-in-out infinite;
}
@keyframes glint { 0%, 72% { left: -60%; } 88%, 100% { left: 130%; } }

.icon-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 36px; height: 36px; border: 1px solid var(--line);
  background: rgba(9, 13, 17, 0.7); color: var(--muted); font-size: 13px;
  transition: color 0.15s, background 0.15s, border-color 0.15s;
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));
}
.icon-btn:hover { color: #fff; background: rgba(229, 56, 59, 0.16); border-color: rgba(229,56,59,0.5); }
.icon-btn.muted { color: var(--red); }
.close-btn { width: 40px; height: 40px; font-size: 15px; }

/* =========================================================
   HUD
   ========================================================= */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud-top {
  position: absolute; top: calc(16px + var(--safe-top)); left: 18px; right: 18px;
  display: flex; justify-content: space-between; align-items: flex-start; gap: 20px;
}
.hud-left { display: flex; flex-direction: column; gap: 9px; min-width: 250px; }
.hud-brand {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--font-display); font-size: 13px; letter-spacing: 0.12em; color: #d7dee2;
  text-shadow: 0 2px 8px rgba(0,0,0,0.8);
}
.brand-dot { width: 6px; height: 6px; background: var(--red); box-shadow: 0 0 8px var(--red); animation: blink 1.8s infinite; }
@keyframes blink { 0%, 42%, 100% { opacity: 1; } 55%, 78% { opacity: 0.25; } }
.brand-sub { color: var(--dim); font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.2em; margin-left: 3px; }

.health-panel {
  width: 272px; padding: 9px 12px 10px;
  background: linear-gradient(130deg, rgba(10,14,18,0.92), rgba(14,18,22,0.72));
  border: 1px solid var(--line); backdrop-filter: blur(6px);
  clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 11px 100%, 0 calc(100% - 11px));
}
.health-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 6px; }
.health-head span:first-child { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.25em; color: var(--dim); }
#hp-text { font-family: var(--font-mono); font-size: 18px; font-weight: 700; color: #fff; line-height: 1; letter-spacing: -0.03em; }
#hp-text.low { color: var(--red-bright); animation: hpPulse 0.7s infinite; }
@keyframes hpPulse { 50% { opacity: 0.55; } }
.health-bar { height: 9px; background: rgba(255,255,255,0.08); }
.health-bar .bar-fill { background: linear-gradient(90deg, #b7171c, #ff4b4e); box-shadow: 0 0 10px rgba(229,56,59,0.5); }
.health-bar .bar-fill.low { background: linear-gradient(90deg, #8e0e12, #ff2d31); animation: lowGlow 0.65s infinite; }
@keyframes lowGlow { 50% { box-shadow: 0 0 18px rgba(255,45,49,0.9); } }
.shield-bar { height: 5px; margin-top: 4px; }
.shield-bar .bar-fill { background: linear-gradient(90deg, #2b8ba7, #63d8ff); box-shadow: 0 0 8px rgba(76,201,240,0.5); }

.hud-center { display: flex; flex-direction: column; align-items: center; gap: 4px; flex: 1; }
.wave-wrap { display: flex; flex-direction: column; align-items: center; }
.wave-pill {
  display: flex; align-items: stretch; height: 44px;
  background: rgba(10,14,18,0.86); border: 1px solid var(--line-strong);
  clip-path: polygon(10px 0, calc(100% - 10px) 0, 100% 100%, 0 100%);
  box-shadow: 0 8px 26px rgba(0,0,0,0.45);
}
.wave-pill .wave-label {
  display: flex; align-items: center; padding: 0 12px;
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.24em; color: var(--muted);
  border-right: 1px solid var(--line);
}
#wave-num {
  display: flex; align-items: center; padding: 0 16px;
  font-family: var(--font-display); font-size: 24px; letter-spacing: 0.03em; color: var(--amber);
  text-shadow: 0 0 18px rgba(255,183,3,0.3); line-height: 1;
}
.wave-sub {
  display: flex; align-items: center; gap: 6px; margin-top: 5px;
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.2em; color: var(--muted);
  text-shadow: 0 1px 4px #000;
}
.pulse-dot { width: 4px; height: 4px; background: var(--red-bright); border-radius: 50%; box-shadow: 0 0 7px var(--red); animation: blink 1.1s infinite; }
#enemies-num { color: #dbe2e6; }

.boss-bar {
  margin-top: 9px; width: min(430px, 46vw); padding: 7px 11px 9px;
  background: rgba(12,7,8,0.92); border: 1px solid rgba(229,56,59,0.4);
  box-shadow: 0 0 30px rgba(229,56,59,0.16), inset 0 0 24px rgba(229,56,59,0.05);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  animation: bossIn 0.35s ease-out;
}
@keyframes bossIn { from { opacity: 0; transform: translateY(-8px); } }
.boss-head { display: flex; align-items: center; gap: 7px; margin-bottom: 5px; font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.2em; color: #ffb3b5; }
.boss-head #boss-name { flex: 1; color: #ffdadb; letter-spacing: 0.18em; }
.boss-skull { color: var(--red-bright); font-size: 12px; }
#boss-hp-text { color: var(--muted); letter-spacing: 0.06em; }
.boss-hp { height: 7px; background: rgba(255,255,255,0.07); }
.boss-hp .bar-fill { background: linear-gradient(90deg, #7d1416, #e5383b 55%, #ff7376); box-shadow: 0 0 12px rgba(229,56,59,0.55); transition: width 0.12s linear; }

.hud-right { display: flex; justify-content: flex-end; align-items: flex-start; gap: 7px; min-width: 250px; }
.stat-chip {
  display: flex; align-items: center; gap: 7px; height: 36px; padding: 0 12px;
  background: rgba(10,14,18,0.82); border: 1px solid var(--line);
  font-family: var(--font-mono); font-size: 13px; font-weight: 700; color: #f0f4f6;
  backdrop-filter: blur(6px);
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));
}
.coin-chip { color: var(--amber); min-width: 66px; justify-content: center; }
.coin-icon {
  display: inline-flex; align-items: center; justify-content: center;
  width: 17px; height: 17px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #ffe29a, #ffb703 55%, #b87a00);
  color: #5d3b00; font-size: 11px; font-weight: 900;
  box-shadow: 0 0 8px rgba(255,183,3,0.45); text-shadow: 0 1px 0 rgba(255,255,255,0.4);
}
.score-chip { gap: 10px; }
.stat-label { font-size: 7px; letter-spacing: 0.2em; color: var(--dim); font-weight: 400; }
#score-num { font-size: 13px; min-width: 32px; }
.coin-chip.bump { animation: coinBump 0.3s ease-out; }
@keyframes coinBump { 40% { transform: scale(1.13); background: rgba(255,183,3,0.2); } }

/* minimap */
.minimap-wrap {
  position: absolute; top: 112px; right: 18px; width: 148px;
  padding: 6px; background: rgba(8,11,14,0.76); border: 1px solid var(--line);
  backdrop-filter: blur(5px);
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  opacity: 0.92;
}
.minimap-head { display: flex; justify-content: space-between; align-items: center; padding: 0 2px 5px; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.24em; color: var(--dim); }
.live-dot { width: 4px; height: 4px; border-radius: 50%; background: var(--green); box-shadow: 0 0 6px var(--green); }
#minimap { width: 136px; height: 136px; display: block; background: rgba(4,7,9,0.8); }

/* bottom */
.hud-bottom {
  position: absolute; left: 18px; right: 18px; bottom: calc(16px + var(--safe-bottom));
  display: flex; align-items: flex-end; justify-content: space-between; gap: 18px;
}
.weapon-list { display: flex; gap: 7px; pointer-events: auto; }
.weapon-card {
  position: relative; width: 126px; height: 66px; padding: 8px 10px 9px;
  background: linear-gradient(150deg, rgba(15,20,25,0.9), rgba(8,11,14,0.9));
  border: 1px solid var(--line); cursor: pointer; overflow: hidden;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  transition: border-color 0.15s, transform 0.15s, background 0.15s;
  text-align: left;
}
.weapon-card:hover { transform: translateY(-2px); border-color: rgba(255,255,255,0.28); }
.weapon-card.active { border-color: var(--amber); background: linear-gradient(150deg, rgba(42,33,11,0.92), rgba(12,12,10,0.92)); }
.weapon-card.active::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--amber); box-shadow: 0 0 10px var(--amber); }
.weapon-card.empty { opacity: 0.5; }
.weapon-card.reloading { border-color: rgba(76,201,240,0.45); }
.wc-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
.wc-key {
  display: inline-flex; align-items: center; justify-content: center;
  width: 16px; height: 16px; border: 1px solid var(--line-strong);
  font-family: var(--font-mono); font-size: 8px; color: var(--muted);
}
.weapon-card.active .wc-key { border-color: rgba(255,183,3,0.5); color: var(--amber); }
.wc-name { font-family: var(--font-ui); font-weight: 800; font-size: 9px; letter-spacing: 0.12em; color: #cfd8dd; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.weapon-card.active .wc-name { color: #fff; }
.wc-ammo { display: flex; align-items: baseline; gap: 4px; font-family: var(--font-mono); line-height: 1; }
.wc-mag { font-size: 21px; font-weight: 700; color: #f0f4f6; letter-spacing: -0.04em; }
.weapon-card.active .wc-mag { color: var(--amber-soft); }
.wc-res { font-size: 9px; color: var(--dim); }
.wc-reload { position: absolute; left: 0; bottom: 0; height: 2px; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); width: 0; transition: width 0.08s linear; }
.wc-dry { position: absolute; right: 9px; bottom: 8px; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.1em; color: var(--red-bright); }
.weapon-card::after {
  content: ""; position: absolute; right: 8px; top: 10px; width: 26px; height: 7px; opacity: 0.18;
  background: currentColor; clip-path: polygon(0 25%, 65% 25%, 65% 0, 100% 50%, 65% 100%, 65% 75%, 0 75%);
  color: var(--amber);
}
.weapon-card[data-weapon="shotgun"]::after { width: 30px; height: 5px; }
.weapon-card[data-weapon="smg"]::after { width: 24px; height: 9px; }

.power-list { display: flex; flex-direction: column; gap: 5px; align-items: center; flex: 1; }
.power-chip {
  display: flex; align-items: center; gap: 7px; height: 27px; padding: 0 10px;
  background: rgba(8,12,15,0.86); border: 1px solid rgba(157,255,77,0.3);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.12em; color: var(--toxic);
  clip-path: polygon(0 0, calc(100% - 7px) 0, 100% 7px, 100% 100%, 7px 100%, 0 calc(100% - 7px));
  animation: powerIn 0.25s ease-out;
}
@keyframes powerIn { from { opacity: 0; transform: translateY(6px); } }
.power-chip .p-icon { font-size: 11px; }
.power-chip .p-time { color: #d9f7c4; }
.power-chip.shield { border-color: rgba(76,201,240,0.4); color: var(--cyan); }
.power-chip.damage { border-color: rgba(229,56,59,0.4); color: #ff8a8c; }
.power-chip.slow { border-color: rgba(150,190,255,0.4); color: #bcd8ff; }

.control-hint {
  display: flex; gap: 12px; align-items: center; max-width: 46vw; flex-wrap: wrap; justify-content: flex-end;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.1em; color: var(--dim);
  text-shadow: 0 1px 3px #000; transition: opacity 0.8s ease;
}
.control-hint b { color: #9ba7b1; font-weight: 700; }
.control-hint.fade { opacity: 0; }

/* wave banner */
.wave-banner {
  position: absolute; left: 50%; top: 31%; transform: translate(-50%, -50%);
  display: flex; flex-direction: column; align-items: center; gap: 7px;
  opacity: 0; pointer-events: none; width: min(90vw, 640px);
}
.wave-banner.show { animation: banner 2.6s ease-out forwards; }
@keyframes banner {
  0% { opacity: 0; transform: translate(-50%, -44%) scale(0.96); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -53%) scale(1.01); }
}
.banner-title {
  font-family: var(--font-display); font-size: clamp(30px, 5vw, 58px); letter-spacing: 0.06em;
  color: #fff; text-transform: uppercase; text-shadow: 0 0 36px rgba(229,56,59,0.55), 0 4px 0 rgba(0,0,0,0.6);
  white-space: nowrap;
}
.banner-sub { font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.45em; color: var(--amber); text-shadow: 0 1px 8px #000; }
.banner-line { width: 100%; height: 1px; background: linear-gradient(90deg, transparent, rgba(255,255,255,0.34), transparent); }
.wave-banner.boss .banner-title { color: #ff6b6d; text-shadow: 0 0 44px rgba(229,56,59,0.8), 0 4px 0 rgba(0,0,0,0.7); }

/* toasts */
.toast {
  position: absolute; left: 50%; bottom: 112px; transform: translate(-50%, 10px);
  padding: 8px 16px; background: rgba(8,12,15,0.92); border: 1px solid var(--line-strong);
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.18em; color: #e7edf0;
  opacity: 0; transition: opacity 0.2s ease, transform 0.2s ease; white-space: nowrap;
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.warn { color: var(--amber); border-color: rgba(255,183,3,0.4); }
.toast.danger { color: #ff9a9c; border-color: rgba(229,56,59,0.45); }

/* =========================================================
   MOBILE CONTROLS
   ========================================================= */
.mobile-controls { display: none; }
body.touch .mobile-controls { display: block; }
.joystick {
  position: absolute; bottom: calc(22px + var(--safe-bottom)); width: 132px; height: 132px;
  pointer-events: auto; touch-action: none; z-index: 14;
}
.joystick[data-stick="move"] { left: 18px; }
.joystick[data-stick="aim"] { right: 18px; }
.stick-base {
  position: absolute; inset: 0; border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.18);
  background: radial-gradient(circle, rgba(20,28,34,0.5), rgba(6,9,12,0.25) 55%, transparent 70%);
  box-shadow: inset 0 0 30px rgba(0,0,0,0.5);
}
.stick-base::before, .stick-base::after {
  content: ""; position: absolute; background: rgba(255,255,255,0.13);
}
.stick-base::before { left: 50%; top: 16%; bottom: 16%; width: 1px; }
.stick-base::after { top: 50%; left: 16%; right: 16%; height: 1px; }
.stick-knob {
  position: absolute; left: 50%; top: 50%; width: 54px; height: 54px; margin: -27px 0 0 -27px;
  border-radius: 50%; border: 1px solid rgba(255,183,3,0.5);
  background: radial-gradient(circle at 38% 32%, rgba(255,210,120,0.3), rgba(36,29,15,0.85) 70%);
  box-shadow: 0 0 20px rgba(255,183,3,0.15), inset 0 0 12px rgba(0,0,0,0.5);
  transition: transform 0.06s linear;
}
.joystick[data-stick="aim"] .stick-knob { border-color: rgba(229,56,59,0.55); background: radial-gradient(circle at 38% 32%, rgba(255,120,120,0.3), rgba(38,15,16,0.85) 70%); box-shadow: 0 0 20px rgba(229,56,59,0.15), inset 0 0 12px rgba(0,0,0,0.5); }
.stick-label {
  position: absolute; left: 0; right: 0; bottom: -16px; text-align: center;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.25em; color: rgba(255,255,255,0.35);
}
.mobile-actions {
  position: absolute; right: 26px; bottom: calc(176px + var(--safe-bottom));
  display: flex; flex-direction: column; gap: 8px; z-index: 15; pointer-events: auto;
}
.mob-btn {
  width: 66px; height: 40px; border: 1px solid rgba(255,255,255,0.24);
  background: rgba(10,14,18,0.75); font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.12em;
  color: #dbe3e7; backdrop-filter: blur(4px);
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));
}
.mob-btn:active { background: rgba(229,56,59,0.35); }
.dash-btn { border-color: rgba(255,183,3,0.35); color: var(--amber); }

/* =========================================================
   OVERLAYS
   ========================================================= */
.overlay {
  position: absolute; inset: 0; z-index: 30;
  display: flex; align-items: center; justify-content: center;
  padding: 24px; background: rgba(3,5,7,0.66);
  opacity: 0; visibility: hidden; pointer-events: none;
  transition: opacity 0.28s ease, visibility 0.28s;
  backdrop-filter: blur(3px);
}
.overlay.active { opacity: 1; visibility: visible; pointer-events: auto; }

/* ---------- menu ---------- */
.menu-overlay {
  justify-content: flex-start;
  background:
    linear-gradient(90deg, rgba(3,5,8,0.94) 0%, rgba(3,5,8,0.8) 32%, rgba(3,5,8,0.24) 62%, rgba(3,5,8,0.5) 100%),
    radial-gradient(ellipse at 72% 45%, transparent 20%, rgba(3,5,8,0.35) 75%);
  backdrop-filter: none;
  padding: 0;
}
.menu-inner {
  position: relative; width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: space-between;
  padding: 5vh 6vw 8vh; gap: 40px;
}
.menu-panel { max-width: 620px; }
.game-title { display: flex; flex-direction: column; line-height: 0.82; margin: 18px 0 0; }
.title-top {
  font-family: var(--font-display); font-size: clamp(58px, 9.2vw, 132px); letter-spacing: 0.035em;
  color: #f2f5f4; text-shadow: 0 6px 0 rgba(0,0,0,0.35), 0 0 80px rgba(255,255,255,0.08);
  transform: scaleX(1.01); transform-origin: left;
}
.title-bottom {
  position: relative; font-family: var(--font-display); font-size: clamp(58px, 9.2vw, 132px);
  letter-spacing: 0.02em; color: var(--red); transform: scaleX(1.02); transform-origin: left; margin-top: 4px;
  text-shadow: 0 5px 0 #4d0b0d, 0 0 60px rgba(229,56,59,0.28);
}
.title-bottom::after {
  content: attr(data-text); position: absolute; left: 3px; top: 2px; width: 100%;
  color: rgba(255,255,255,0.05); clip-path: inset(58% 0 10% 0); pointer-events: none;
}
.tagline {
  margin: 24px 0 0; font-size: clamp(14px, 1.4vw, 18px); line-height: 1.55; color: var(--muted);
  letter-spacing: 0.05em; font-weight: 400;
}
.tagline em { color: #d9e1e5; font-style: normal; font-weight: 700; }
.menu-actions { display: flex; align-items: center; gap: 12px; margin-top: 34px; flex-wrap: wrap; }
.menu-meta { display: flex; gap: 1px; margin-top: 34px; border: 1px solid var(--line); width: fit-content; background: var(--line); }
.meta-cell { padding: 9px 18px 10px; background: rgba(7,10,13,0.75); min-width: 96px; }
.meta-cell span { display: block; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.2em; color: var(--dim); margin-bottom: 3px; }
.meta-cell strong { font-family: var(--font-display); font-size: 19px; letter-spacing: 0.03em; color: #e7ecee; }
.menu-controls {
  display: flex; flex-wrap: wrap; gap: 16px; margin-top: 26px;
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.12em; color: #6f7b86;
}
.menu-controls b { color: #b8c1c8; }
.mobile-menu-note { display: none; margin-top: 22px; font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.16em; color: var(--amber); }
.menu-side {
  align-self: flex-end; margin-bottom: 8vh; max-width: 280px; text-align: right;
  display: flex; flex-direction: column; align-items: flex-end; gap: 14px; opacity: 0.85;
}
.side-rule { width: 1px; height: 64px; background: linear-gradient(180deg, transparent, rgba(255,183,3,0.5)); }
.side-quote { font-size: 13px; line-height: 1.6; color: #aab5bd; font-style: italic; }
.side-cite { font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.16em; color: var(--dim); }
.side-stamp {
  margin-top: 8px; padding: 9px 13px; border: 1px dashed rgba(229,56,59,0.5); color: var(--red-bright);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.18em; line-height: 1.5;
  transform: rotate(-3deg); opacity: 0.8;
}
.side-stamp span { color: var(--muted); font-size: 7px; }
.menu-footer {
  position: absolute; left: 6vw; right: 6vw; bottom: calc(18px + var(--safe-bottom));
  display: flex; justify-content: space-between; gap: 20px;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.16em; color: #4d5862;
}
.menu-mute { cursor: pointer; }
.menu-mute:hover { color: var(--muted); }

/* ---------- modals ---------- */
.modal-panel { width: min(560px, 100%); padding: 30px 32px 26px; }
.modal-panel.compact { width: min(460px, 100%); }
.modal-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; margin-bottom: 22px; }
.modal-panel h2 { font-family: var(--font-display); font-size: clamp(30px, 4vw, 42px); letter-spacing: 0.025em; margin-top: 6px; line-height: 1; }
.modal-copy { margin-top: 10px; color: var(--muted); font-size: 12px; line-height: 1.6; }
.modal-actions { display: flex; flex-direction: column; gap: 8px; margin-top: 24px; }
.modal-actions.horizontal { flex-direction: row; justify-content: center; align-items: center; flex-wrap: wrap; }
.pause-stats { display: flex; justify-content: center; gap: 1px; margin-top: 22px; border: 1px solid var(--line); background: var(--line); }
.pause-stats div { flex: 1; padding: 10px 8px; background: rgba(7,10,13,0.85); text-align: center; }
.pause-stats span { display: block; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.16em; color: var(--dim); margin-bottom: 4px; }
.pause-stats strong { font-family: var(--font-display); font-size: 20px; color: #eef2f4; }
.manual-note { margin-top: 16px; font-size: 10px; line-height: 1.6; color: var(--dim); }
.manual-note kbd { height: 18px; min-width: 18px; font-size: 8px; }
.coin-inline { display: inline-flex; width: 12px; height: 12px; border-radius: 50%; background: var(--amber); color: #3b2700; font-size: 8px; align-items: center; justify-content: center; vertical-align: -1px; margin-right: 1px; }

/* how to play */
.howto-overlay { z-index: 40; }
.howto-overlay .modal-panel { width: min(920px, 100%); max-height: 92vh; overflow-y: auto; scrollbar-width: thin; }
.howto-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 28px; margin: 6px 0 24px; }
.howto-grid h3 {
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.25em; color: var(--amber);
  margin-bottom: 12px; padding-bottom: 7px; border-bottom: 1px solid var(--line);
}
.key-list, .enemy-list, .weapon-help { list-style: none; display: flex; flex-direction: column; gap: 9px; }
.key-list li { display: flex; align-items: center; gap: 10px; font-size: 11px; color: var(--muted); }
.keys { display: flex; gap: 2px; min-width: 88px; }
.key-list kbd { min-width: 19px; height: 19px; font-size: 8px; }
.enemy-list li { display: flex; gap: 9px; align-items: flex-start; }
.enemy-dot { width: 9px; height: 9px; margin-top: 3px; flex: none; border-radius: 50%; }
.enemy-dot.walker { background: #7d9a52; box-shadow: 0 0 7px rgba(125,154,82,0.6); }
.enemy-dot.runner { background: #c4b69a; }
.enemy-dot.spitter { background: #9b6bb5; }
.enemy-dot.brute { background: #4f6b3c; }
.enemy-dot.screamer { background: #d6c84a; }
.enemy-dot.boss { background: var(--red); box-shadow: 0 0 8px var(--red); }
.enemy-list b, .weapon-help b { display: block; font-size: 10px; letter-spacing: 0.1em; color: #dbe2e6; }
.enemy-list small, .weapon-help small { display: block; font-size: 9.5px; line-height: 1.45; color: var(--dim); margin-top: 2px; }
.weapon-help li { position: relative; padding-bottom: 8px; border-bottom: 1px solid rgba(255,255,255,0.05); }
.ammo-type { position: absolute; right: 0; top: 0; font-family: var(--font-mono); font-size: 8px; color: var(--amber); }
.howto-overlay .btn-primary { width: 100%; }

/* ---------- upgrades ---------- */
.upgrade-overlay { background: rgba(3,5,8,0.76); backdrop-filter: blur(5px); }
.upgrade-panel { width: min(1040px, 100%); padding: 28px 30px 24px; max-height: 94vh; overflow-y: auto; scrollbar-width: thin; }
.upgrade-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 24px; margin-bottom: 20px; }
.upgrade-head h2 { font-family: var(--font-display); font-size: clamp(26px, 3.4vw, 40px); letter-spacing: 0.02em; margin-top: 5px; }
.wave-bonus { text-align: right; padding: 10px 14px; border: 1px solid rgba(255,183,3,0.28); background: rgba(255,183,3,0.05); flex: none; }
.wave-bonus span { display: block; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.18em; color: var(--dim); }
.wave-bonus strong { font-family: var(--font-display); font-size: 24px; color: var(--amber); }
.upgrade-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.upgrade-card {
  position: relative; padding: 18px 16px 58px; min-height: 200px; text-align: left;
  background: linear-gradient(155deg, rgba(19,26,32,0.95), rgba(9,12,16,0.96));
  border: 1px solid var(--line); transition: border-color 0.16s, transform 0.16s, background 0.16s;
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  overflow: hidden;
}
.upgrade-card::before { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 80% 0%, rgba(255,183,3,0.08), transparent 55%); pointer-events: none; }
.upgrade-card:not(.sold):not(.locked):hover { border-color: rgba(255,183,3,0.45); transform: translateY(-3px); background: linear-gradient(155deg, rgba(27,34,38,0.98), rgba(11,14,17,0.98)); }
.upgrade-card.sold { opacity: 0.45; border-color: rgba(138,201,38,0.4); }
.upgrade-card.locked { opacity: 0.55; }
.upgrade-card.sold::after {
  content: "AUGMENT INSTALLED"; position: absolute; left: 0; right: 0; top: 42%; padding: 6px 0; text-align: center;
  background: rgba(138,201,38,0.14); color: var(--green); font-family: var(--font-mono); font-size: 8px;
  letter-spacing: 0.2em; transform: rotate(-3deg); border-top: 1px solid rgba(138,201,38,0.35); border-bottom: 1px solid rgba(138,201,38,0.35);
}
.uc-top { display: flex; justify-content: space-between; align-items: flex-start; }
.uc-icon {
  display: inline-flex; align-items: center; justify-content: center; width: 42px; height: 42px;
  border: 1px solid rgba(255,183,3,0.3); background: rgba(255,183,3,0.06);
  font-size: 18px; color: var(--amber);
}
.uc-level { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.14em; color: var(--dim); }
.uc-name { margin-top: 13px; font-family: var(--font-display); font-size: 16px; letter-spacing: 0.04em; color: #f0f4f6; }
.uc-desc { margin-top: 6px; font-size: 10.5px; line-height: 1.5; color: var(--muted); min-height: 32px; }
.uc-pips { display: flex; gap: 3px; margin-top: 11px; }
.uc-pip { width: 14px; height: 3px; background: rgba(255,255,255,0.1); }
.uc-pip.on { background: var(--amber); box-shadow: 0 0 6px rgba(255,183,3,0.4); }
.uc-buy {
  position: absolute; left: 16px; right: 16px; bottom: 14px; height: 34px;
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 12px;
  border: 1px solid rgba(255,183,3,0.34); background: rgba(255,183,3,0.08);
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.12em; color: var(--amber);
  transition: background 0.15s, border-color 0.15s;
}
.uc-buy:hover { background: rgba(255,183,3,0.18); border-color: var(--amber); }
.uc-buy .cost { color: #ffe6a8; font-weight: 700; }
.upgrade-card.locked .uc-buy { border-color: rgba(229,56,59,0.28); color: #ff8b8d; background: rgba(229,56,59,0.07); cursor: not-allowed; }
.upgrade-card.sold .uc-buy { display: none; }
.upgrade-footer { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-top: 20px; }
.upgrade-tip { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.1em; color: var(--dim); }
.upgrade-footer .btn { flex: none; }

/* ---------- game over ---------- */
.gameover-overlay { background: radial-gradient(ellipse at center, rgba(30,5,6,0.62), rgba(3,4,6,0.94) 75%); backdrop-filter: blur(4px); }
.gameover-inner { text-align: center; width: min(640px, 100%); }
.death-title {
  position: relative; font-family: var(--font-display); font-size: clamp(64px, 12vw, 144px);
  line-height: 0.85; color: #e5383b; letter-spacing: 0.01em; margin: 16px 0 10px;
  text-shadow: 0 6px 0 #47090b, 0 0 80px rgba(229,56,59,0.45);
  animation: deathIn 0.7s cubic-bezier(.16,1,.3,1);
}
.death-title::after {
  content: attr(data-text); position: absolute; left: 4px; top: 3px; width: 100%; color: rgba(255,255,255,0.06);
  clip-path: inset(45% 0 25% 0);
}
@keyframes deathIn { from { opacity: 0; transform: scale(1.16); filter: blur(8px); } }
.death-sub { color: var(--muted); font-size: 13px; letter-spacing: 0.04em; }
.result-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; margin: 28px auto 0; background: var(--line); border: 1px solid var(--line); max-width: 640px; }
.result-cell { padding: 13px 8px 14px; background: rgba(7,10,13,0.85); }
.result-cell span { display: block; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.16em; color: var(--dim); margin-bottom: 5px; }
.result-cell strong { font-family: var(--font-display); font-size: 24px; color: #eef2f4; }
.result-cell:nth-child(1) strong { color: var(--amber); }
.new-best { margin-top: 14px; font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.3em; color: var(--amber); animation: blink 1.4s infinite; }
.gameover-inner .modal-actions { margin-top: 26px; }

/* =========================================================
   RESPONSIVE
   ========================================================= */
@media (max-width: 1100px) {
  .hud-left { min-width: 210px; }
  .health-panel { width: 230px; }
  .hud-right { min-width: 210px; }
  .score-chip .stat-label { display: none; }
  .weapon-card { width: 112px; }
  .control-hint { display: none; }
  .menu-side { display: none; }
}

@media (max-width: 760px) {
  .overlay { padding: 14px; }
  .hud-top { top: calc(10px + var(--safe-top)); left: 10px; right: 10px; gap: 8px; }
  .hud-brand { display: none; }
  .hud-left { min-width: 0; }
  .health-panel { width: 44vw; max-width: 190px; padding: 7px 9px 8px; }
  .health-head span:first-child { display: none; }
  #hp-text { font-size: 15px; }
  .health-bar { height: 7px; }
  .wave-pill { height: 36px; }
  .wave-label { display: none; }
  #wave-num { font-size: 19px; padding: 0 12px; }
  .wave-sub { font-size: 7px; }
  .hud-right { min-width: 0; gap: 5px; }
  .stat-chip { height: 30px; padding: 0 8px; font-size: 11px; }
  .coin-chip { min-width: 48px; }
  .score-chip { display: none; }
  .icon-btn { width: 31px; height: 31px; font-size: 11px; }
  .icon-btn .pause-glyph { font-size: 9px; }
  .minimap-wrap { display: none; }
  .boss-bar { width: 68vw; }
  .boss-head { font-size: 7px; }
  .hud-bottom { left: 10px; right: 10px; bottom: calc(8px + var(--safe-bottom)); flex-direction: column; align-items: stretch; gap: 8px; }
  .weapon-list { gap: 5px; justify-content: center; margin-bottom: 138px; }
  .weapon-card { width: 31vw; max-width: 118px; height: 57px; padding: 6px 7px; }
  .wc-name { font-size: 7.5px; letter-spacing: 0.08em; }
  .wc-key { width: 13px; height: 13px; font-size: 7px; }
  .wc-mag { font-size: 17px; }
  .wc-res { font-size: 7.5px; }
  .weapon-card::after { display: none; }
  .power-list { position: absolute; left: 0; right: 0; bottom: 120px; flex-direction: row; justify-content: center; flex-wrap: wrap; }
  .power-chip { height: 23px; font-size: 7px; }
  .toast { bottom: 260px; font-size: 8px; max-width: 86vw; white-space: normal; text-align: center; }
  .wave-banner { top: 28%; }
  .wave-banner.boss { top: 33%; }

  .menu-inner { padding: 7vh 7vw; }
  .menu-overlay { background: linear-gradient(90deg, rgba(3,5,8,0.93), rgba(3,5,8,0.68)), radial-gradient(ellipse at 70% 30%, rgba(229,56,59,0.08), transparent 60%); }
  .menu-panel { max-width: 100%; }
  .title-top, .title-bottom { font-size: clamp(52px, 17vw, 92px); }
  .tagline { margin-top: 16px; font-size: 13px; }
  .menu-actions { margin-top: 24px; }
  .btn-lg { height: 52px; padding: 0 26px; font-size: 12px; width: 100%; }
  .menu-actions .btn { width: 100%; }
  .menu-meta { margin-top: 22px; width: 100%; }
  .meta-cell { flex: 1; min-width: 0; padding: 8px 10px; }
  .menu-controls { display: none; }
  .mobile-menu-note { display: block; }
  .menu-footer { left: 7vw; right: 7vw; bottom: calc(12px + var(--safe-bottom)); }
  .menu-footer span:nth-child(2) { display: none; }

  .modal-panel { padding: 22px 20px 20px; }
  .modal-head { margin-bottom: 16px; }
  .howto-grid { grid-template-columns: 1fr; gap: 22px; }
  .howto-overlay .modal-panel { max-height: 88vh; }
  .result-grid { grid-template-columns: repeat(2, 1fr); }
  .gameover-inner .modal-actions.horizontal { flex-direction: column; }
  .gameover-inner .modal-actions .btn { width: 100%; }
  .death-title { font-size: clamp(56px, 18vw, 100px); }

  .upgrade-panel { padding: 20px 16px 18px; max-height: 92vh; }
  .upgrade-head { gap: 10px; margin-bottom: 14px; }
  .upgrade-head h2 { font-size: 26px; }
  .upgrade-head .modal-copy { font-size: 10px; }
  .wave-bonus { padding: 7px 9px; }
  .wave-bonus strong { font-size: 18px; }
  .upgrade-grid { grid-template-columns: 1fr; gap: 8px; }
  .upgrade-card { min-height: 0; padding: 12px 12px 48px; display: flex; flex-direction: column; gap: 0; }
  .uc-top { align-items: center; }
  .uc-icon { width: 34px; height: 34px; font-size: 15px; }
  .uc-name { margin-top: 8px; font-size: 14px; }
  .uc-desc { font-size: 9.5px; min-height: 0; margin-top: 3px; }
  .uc-pips { margin-top: 7px; }
  .uc-buy { left: 12px; right: 12px; bottom: 10px; height: 29px; font-size: 8px; }
  .upgrade-footer { flex-direction: column; align-items: stretch; gap: 10px; }
  .upgrade-tip { text-align: center; }
  .upgrade-footer .btn { width: 100%; }
}

@media (pointer: coarse) {
  body.playing #game { cursor: default; }
  .control-hint { display: none; }
}

@media (max-height: 540px) {
  .menu-inner { padding-top: 3vh; padding-bottom: 3vh; }
  .title-top, .title-bottom { font-size: clamp(38px, 11vh, 72px); }
  .tagline { display: none; }
  .menu-meta { margin-top: 14px; }
  .menu-actions { margin-top: 16px; }
  .menu-controls { display: none; }
  .wave-banner { top: 26%; }
  .upgrade-card { min-height: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

// Shared math and small canvas helpers.
export const TAU = Math.PI * 2;
export const PI = Math.PI;

export const clamp = (v, min, max) => (v < min ? min : v > max ? max : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (min = 0, max = 1) => min + Math.random() * (max - min);
export const randInt = (min, max) => Math.floor(rand(min, max + 1));
export const chance = (p) => Math.random() < p;
export const pick = (arr) => arr[(Math.random() * arr.length) | 0];
export const sign = (v) => (v < 0 ? -1 : 1);

export function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = (Math.random() * (i + 1)) | 0;
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function dist2(ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  return dx * dx + dy * dy;
}

export function dist(ax, ay, bx, by) {
  return Math.hypot(bx - ax, by - ay);
}

export function angleTo(ax, ay, bx, by) {
  return Math.atan2(by - ay, bx - ax);
}

export function angleDiff(a, b) {
  let d = (b - a + PI * 3) % TAU - PI;
  return d;
}

export function angleLerp(a, b, t) {
  return a + angleDiff(a, b) * t;
}

export function norm(x, y) {
  const l = Math.hypot(x, y);
  if (l < 0.00001) return { x: 0, y: 0, len: 0 };
  return { x: x / l, y: y / l, len: l };
}

export function smoothDamp(current, target, smoothing, dt) {
  return lerp(current, target, 1 - Math.exp(-smoothing * dt));
}

export function weightedPick(entries, weightFn) {
  let total = 0;
  for (const e of entries) total += Math.max(0, weightFn(e));
  let r = Math.random() * total;
  for (const e of entries) {
    r -= Math.max(0, weightFn(e));
    if (r <= 0) return e;
  }
  return entries[entries.length - 1];
}

// Swept circle vs circle. Returns the earliest t in [0,1] or -1.
export function segCircle(x1, y1, x2, y2, cx, cy, r) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const fx = x1 - cx;
  const fy = y1 - cy;
  const a = dx * dx + dy * dy;
  if (a < 0.00001) return dist2(x1, y1, cx, cy) <= r * r ? 0 : -1;
  const b = 2 * (fx * dx + fy * dy);
  const c = fx * fx + fy * fy - r * r;
  let disc = b * b - 4 * a * c;
  if (disc < 0) return -1;
  disc = Math.sqrt(disc);
  const t1 = (-b - disc) / (2 * a);
  const t2 = (-b + disc) / (2 * a);
  if (t1 >= 0 && t1 <= 1) return t1;
  if (t2 >= 0 && t2 <= 1) return t2;
  if (t1 < 0 && t2 > 1) return 0;
  return -1;
}

export function formatNumber(n) {
  if (n >= 1000000) return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
  if (n >= 10000) return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'K';
  return String(Math.floor(n));
}

export function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

export function polygon(ctx, points) {
  if (!points.length) return;
  ctx.beginPath();
  ctx.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  ctx.closePath();
}

export function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w * 0.5, h * 0.5);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

// Deterministic PRNG for floor decoration.
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Tiny WebAudio synthesizer — every sound is generated at runtime.
import { rand, clamp } from './utils.js';
import { STORAGE_KEYS } from './data.js';

export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.muted = false;
    try { this.muted = localStorage.getItem(STORAGE_KEYS.muted) === '1'; } catch { /* ignored */ }
    this.ambience = null;
    this.lastGroan = 0;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return true;
    }
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return false;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.55;
      const comp = this.ctx.createDynamicsCompressor();
      comp.threshold.value = -16;
      comp.knee.value = 16;
      comp.ratio.value = 7;
      comp.attack.value = 0.003;
      comp.release.value = 0.2;
      this.master.connect(comp);
      comp.connect(this.ctx.destination);

      const len = Math.floor(this.ctx.sampleRate * 1.2);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      this.noiseBuffer = buf;
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return true;
    } catch {
      return false;
    }
  }

  unlock() { return this.ensure(); }

  setMuted(v) {
    this.muted = !!v;
    try { localStorage.setItem(STORAGE_KEYS.muted, this.muted ? '1' : '0'); } catch { /* ignored */ }
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(this.muted ? 0 : 0.55, this.ctx.currentTime + 0.08);
    }
    return this.muted;
  }

  toggleMuted() { return this.setMuted(!this.muted); }

  ok() { return !this.muted && this.ensure(); }
  now() { return this.ctx.currentTime; }

  tone({ type = 'sine', freq = 440, to = null, dur = 0.2, gain = 0.2, attack = 0.005, delay = 0, detune = 0 }) {
    if (!this.ok()) return;
    const t0 = this.now() + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (to !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
    osc.detune.value = detune;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  noise({ dur = 0.15, gain = 0.2, filter = 1200, type = 'lowpass', q = 0.8, delay = 0, attack = 0.002 }) {
    if (!this.ok()) return;
    const t0 = this.now() + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(filter, t0);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  // ---------------- weapons ----------------
  shoot(kind = 'pistol') {
    if (!this.ok()) return;
    if (kind === 'pistol') {
      this.noise({ dur: 0.09, gain: 0.28, filter: 2600, type: 'highpass' });
      this.tone({ type: 'square', freq: rand(150, 180), to: 60, dur: 0.1, gain: 0.12 });
      this.tone({ type: 'triangle', freq: rand(620, 680), to: 180, dur: 0.05, gain: 0.05 });
    } else if (kind === 'shotgun') {
      this.noise({ dur: 0.3, gain: 0.5, filter: 950, type: 'lowpass' });
      this.noise({ dur: 0.09, gain: 0.2, filter: 3200, type: 'highpass' });
      this.tone({ type: 'sine', freq: 120, to: 38, dur: 0.28, gain: 0.33 });
    } else {
      this.noise({ dur: 0.055, gain: 0.2, filter: 3400, type: 'highpass' });
      this.tone({ type: 'square', freq: rand(210, 240), to: 90, dur: 0.055, gain: 0.08 });
    }
  }

  empty() {
    this.noise({ dur: 0.025, gain: 0.16, filter: 4200, type: 'highpass' });
    this.tone({ type: 'square', freq: 380, dur: 0.03, gain: 0.04 });
  }

  reload(step = 0) {
    if (!this.ok()) return;
    if (step === 0) {
      this.noise({ dur: 0.05, gain: 0.14, filter: 1800, type: 'bandpass', q: 2 });
      this.tone({ type: 'square', freq: 240, dur: 0.04, gain: 0.03 });
      this.noise({ dur: 0.06, gain: 0.12, filter: 1200, type: 'bandpass', q: 2, delay: 0.18 });
    } else {
      this.noise({ dur: 0.04, gain: 0.18, filter: 2400, type: 'bandpass', q: 3 });
      this.tone({ type: 'square', freq: 520, to: 380, dur: 0.05, gain: 0.045 });
    }
  }

  swap() {
    this.noise({ dur: 0.045, gain: 0.1, filter: 2000, type: 'bandpass', q: 2 });
    this.tone({ type: 'triangle', freq: 300, to: 440, dur: 0.06, gain: 0.04 });
  }

  // ---------------- combat ----------------
  hit(crit = false) {
    if (!this.ok()) return;
    this.noise({ dur: 0.075, gain: crit ? 0.24 : 0.15, filter: crit ? 600 : 900, type: 'lowpass' });
    this.tone({ type: crit ? 'triangle' : 'sine', freq: crit ? 880 : 260, to: crit ? 520 : 140, dur: 0.08, gain: crit ? 0.08 : 0.055 });
  }

  kill() {
    if (!this.ok()) return;
    this.noise({ dur: 0.3, gain: 0.23, filter: 700, type: 'lowpass' });
    this.tone({ type: 'sawtooth', freq: rand(90, 140), to: 38, dur: 0.3, gain: 0.06 });
  }

  hurt() {
    if (!this.ok()) return;
    this.tone({ type: 'sawtooth', freq: 180, to: 42, dur: 0.32, gain: 0.14 });
    this.noise({ dur: 0.18, gain: 0.2, filter: 500, type: 'lowpass' });
  }

  shieldHit() {
    this.tone({ type: 'sine', freq: 900, to: 320, dur: 0.22, gain: 0.1 });
    this.noise({ dur: 0.12, gain: 0.14, filter: 2400, type: 'bandpass', q: 1.5 });
  }

  pickup() {
    this.tone({ type: 'sine', freq: 760, to: 1180, dur: 0.09, gain: 0.07 });
  }

  coin() {
    this.tone({ type: 'square', freq: rand(880, 980), dur: 0.035, gain: 0.025 });
    this.tone({ type: 'sine', freq: 1320, dur: 0.06, gain: 0.045, delay: 0.025 });
  }

  powerup() {
    if (!this.ok()) return;
    [523, 659, 784, 1046].forEach((f, i) => {
      this.tone({ type: 'triangle', freq: f, dur: 0.22, gain: 0.075, delay: i * 0.055 });
    });
  }

  upgrade() {
    if (!this.ok()) return;
    [392, 523, 659].forEach((f, i) => this.tone({ type: 'square', freq: f, dur: 0.18, gain: 0.04, delay: i * 0.06 }));
    this.noise({ dur: 0.2, gain: 0.1, filter: 1800, type: 'bandpass', q: 1.2, delay: 0.05 });
  }

  wave() {
    if (!this.ok()) return;
    this.tone({ type: 'sawtooth', freq: 92, to: 70, dur: 1.1, gain: 0.14 });
    this.tone({ type: 'sawtooth', freq: 138, to: 104, dur: 1.1, gain: 0.07, detune: 8 });
    this.noise({ dur: 0.7, gain: 0.1, filter: 420, type: 'lowpass' });
  }

  boss() {
    if (!this.ok()) return;
    this.tone({ type: 'sawtooth', freq: 55, to: 36, dur: 1.6, gain: 0.26 });
    this.tone({ type: 'square', freq: 82, to: 52, dur: 1.6, gain: 0.1, detune: -14 });
    this.noise({ dur: 1.1, gain: 0.2, filter: 320, type: 'lowpass' });
  }

  growl(intensity = 1) {
    if (!this.ok()) return;
    if (this.ctx.currentTime - this.lastGroan < 0.18) return;
    this.lastGroan = this.ctx.currentTime;
    const base = rand(58, 84) / intensity;
    this.tone({ type: 'sawtooth', freq: base, to: base * 0.75, dur: rand(0.3, 0.6), gain: 0.035 });
    this.tone({ type: 'triangle', freq: base * 2.03, to: base * 1.4, dur: 0.35, gain: 0.018 });
  }

  explosion() {
    if (!this.ok()) return;
    this.noise({ dur: 0.8, gain: 0.55, filter: 620, type: 'lowpass' });
    this.tone({ type: 'sine', freq: 90, to: 24, dur: 0.7, gain: 0.4 });
    this.noise({ dur: 0.2, gain: 0.22, filter: 3200, type: 'highpass', delay: 0.02 });
  }

  dash() {
    this.noise({ dur: 0.22, gain: 0.16, filter: 1400, type: 'bandpass', q: 0.8 });
    this.tone({ type: 'sine', freq: 240, to: 720, dur: 0.16, gain: 0.04 });
  }

  click() {
    this.noise({ dur: 0.035, gain: 0.08, filter: 2200, type: 'bandpass', q: 2 });
  }

  spit() {
    this.noise({ dur: 0.16, gain: 0.13, filter: 700, type: 'bandpass', q: 1 });
    this.tone({ type: 'sine', freq: 220, to: 90, dur: 0.16, gain: 0.06 });
  }

  slam() {
    if (!this.ok()) return;
    this.tone({ type: 'sine', freq: 70, to: 30, dur: 0.5, gain: 0.35 });
    this.noise({ dur: 0.4, gain: 0.3, filter: 500, type: 'lowpass' });
  }

  heartbeat(strength = 1) {
    if (!this.ok()) return;
    this.tone({ type: 'sine', freq: 58, to: 40, dur: 0.13, gain: 0.11 * strength });
    this.tone({ type: 'sine', freq: 52, to: 36, dur: 0.12, gain: 0.07 * strength, delay: 0.19 });
  }

  startAmbience() {
    if (!this.ok() || this.ambience) return;
    const ctx = this.ctx;
    const out = ctx.createGain();
    out.gain.value = 0.0001;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 210;
    filter.Q.value = 3;
    const oscA = ctx.createOscillator();
    oscA.type = 'sawtooth';
    oscA.frequency.value = 42;
    const oscB = ctx.createOscillator();
    oscB.type = 'sawtooth';
    oscB.frequency.value = 42.7;
    const oscC = ctx.createOscillator();
    oscC.type = 'sine';
    oscC.frequency.value = 84.2;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 60;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    oscA.connect(filter);
    oscB.connect(filter);
    oscC.connect(filter);
    filter.connect(out);
    out.connect(this.master);
    oscA.start();
    oscB.start();
    oscC.start();
    lfo.start();
    out.gain.linearRampToValueAtTime(0.09, ctx.currentTime + 4);
    this.ambience = { out, oscA, oscB, oscC, lfo };
  }

  stopAmbience() {
    if (!this.ambience || !this.ctx) return;
    const a = this.ambience;
    this.ambience = null;
    const t = this.ctx.currentTime;
    try {
      a.out.gain.cancelScheduledValues(t);
      a.out.gain.setValueAtTime(a.out.gain.value, t);
      a.out.gain.linearRampToValueAtTime(0.0001, t + 0.8);
      [a.oscA, a.oscB, a.oscC, a.lfo].forEach((o) => o.stop(t + 0.9));
    } catch { /* ignored */ }
  }
}

// Keyboard, mouse and dual-stick touch input.
import { clamp } from './utils.js';

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.mouse = { x: window.innerWidth / 2, y: window.innerHeight / 2, down: false };
    this.mouseJustDown = false;
    this.moveStick = { x: 0, y: 0, mag: 0, active: false };
    this.aimStick = { x: 0, y: 0, mag: 0, active: false };
    this.reloadQueued = false;
    this.dashQueued = false;
    this.pauseQueued = false;
    this.switchTo = null;
    this.cycleQueued = 0;
    this.isTouch = false;
    this._bindKeyboard();
    this._bindMouse();
    this._bindTouchUI();
    this.detectTouch();
  }

  detectTouch() {
    const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
    this.isTouch = coarse || navigator.maxTouchPoints > 0 || 'ontouchstart' in window;
    document.body.classList.toggle('touch', this.isTouch);
    document.body.classList.toggle('desktop', !this.isTouch);
  }

  _bindKeyboard() {
    const gameKeys = new Set([
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
      'Space', 'KeyR', 'KeyQ', 'KeyE', 'Digit1', 'Digit2', 'Digit3', 'Escape', 'KeyP', 'KeyM',
    ]);
    window.addEventListener('keydown', (e) => {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA')) return;
      if (gameKeys.has(e.code)) e.preventDefault();
      this.keys.add(e.code);
      if (e.repeat) return;
      if (e.code === 'KeyR') this.reloadQueued = true;
      if (e.code === 'Space') this.dashQueued = true;
      if (e.code === 'Escape' || e.code === 'KeyP') this.pauseQueued = true;
      if (e.code === 'Digit1') this.switchTo = 0;
      if (e.code === 'Digit2') this.switchTo = 1;
      if (e.code === 'Digit3') this.switchTo = 2;
      if (e.code === 'KeyQ') this.cycleQueued -= 1;
      if (e.code === 'KeyE') this.cycleQueued += 1;
    }, { passive: false });

    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.mouse.down = false;
      this.resetSticks();
    });
  }

  _bindMouse() {
    const move = (e) => {
      if (e.pointerType === 'touch') return;
      this.mouse.x = e.clientX;
      this.mouse.y = e.clientY;
    };
    window.addEventListener('pointermove', move, { passive: true });

    this.canvas.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'touch') return;
      if (e.button !== 0) return;
      this.mouse.down = true;
      this.mouseJustDown = true;
      this.mouse.x = e.clientX;
      this.mouse.y = e.clientY;
      this._markTouch();
    });
    window.addEventListener('pointerup', (e) => {
      if (e.pointerType === 'touch') return;
      if (e.button === 0) this.mouse.down = false;
    });
    window.addEventListener('pointercancel', () => { this.mouse.down = false; });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    this.canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.cycleQueued += e.deltaY > 0 ? 1 : -1;
    }, { passive: false });
  }

  _markTouch() {
    if (!this.isTouch) {
      this.isTouch = true;
      document.body.classList.add('touch');
      document.body.classList.remove('desktop');
    }
  }

  _bindTouchUI() {
    document.querySelectorAll('.joystick').forEach((el) => {
      const base = el.querySelector('.stick-base');
      const knob = el.querySelector('.stick-knob');
      const stick = el.dataset.stick === 'move' ? this.moveStick : this.aimStick;
      let pointerId = null;
      let cx = 0;
      let cy = 0;
      const radius = 40;

      const setFromEvent = (e) => {
        const dx = e.clientX - cx;
        const dy = e.clientY - cy;
        const len = Math.hypot(dx, dy);
        const cl = len > radius ? radius / len : 1;
        const ox = dx * cl;
        const oy = dy * cl;
        const nx = ox / radius;
        const ny = oy / radius;
        const mag = Math.hypot(nx, ny);
        stick.x = nx;
        stick.y = ny;
        stick.mag = mag;
        stick.active = mag > 0.12;
        knob.style.transform = `translate(${ox}px, ${oy}px)`;
      };

      const reset = () => {
        pointerId = null;
        stick.x = 0;
        stick.y = 0;
        stick.mag = 0;
        stick.active = false;
        knob.style.transform = 'translate(0px, 0px)';
        el.classList.remove('engaged');
      };

      el.addEventListener('pointerdown', (e) => {
        if (e.pointerType === 'mouse') return;
        e.preventDefault();
        this._markTouch();
        if (pointerId !== null) return;
        pointerId = e.pointerId;
        const r = base.getBoundingClientRect();
        cx = r.left + r.width / 2;
        cy = r.top + r.height / 2;
        el.classList.add('engaged');
        try { el.setPointerCapture(e.pointerId); } catch { /* ignored */ }
        setFromEvent(e);
      });
      el.addEventListener('pointermove', (e) => {
        if (e.pointerId !== pointerId) return;
        e.preventDefault();
        setFromEvent(e);
      });
      const end = (e) => {
        if (e.pointerId !== pointerId) return;
        reset();
      };
      el.addEventListener('pointerup', end);
      el.addEventListener('pointercancel', end);
      el.addEventListener('lostpointercapture', end);
    });

    document.querySelectorAll('[data-action]').forEach((el) => {
      el.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        const action = el.dataset.action;
        if (action === 'reload') this.reloadQueued = true;
        if (action === 'dash') this.dashQueued = true;
        el.classList.add('pressed');
        setTimeout(() => el.classList.remove('pressed'), 110);
        if (window.navigator.vibrate) window.navigator.vibrate(8);
      });
    });
  }

  resetSticks() {
    this.moveStick.x = this.moveStick.y = this.moveStick.mag = 0;
    this.moveStick.active = false;
    this.aimStick.x = this.aimStick.y = this.aimStick.mag = 0;
    this.aimStick.active = false;
    document.querySelectorAll('.stick-knob').forEach((k) => { k.style.transform = 'translate(0px,0px)'; });
  }

  getMoveVector() {
    let x = 0;
    let y = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y -= 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (x !== 0 || y !== 0) {
      const l = Math.hypot(x, y);
      return { x: x / l, y: y / l, mag: 1, source: 'key' };
    }
    if (this.moveStick.active) {
      return { x: this.moveStick.x, y: this.moveStick.y, mag: clamp(this.moveStick.mag, 0, 1), source: 'stick' };
    }
    return { x: 0, y: 0, mag: 0, source: 'none' };
  }

  get aimsWithStick() { return this.aimStick.active && this.aimStick.mag > 0.2; }
  get firing() { return this.mouse.down || this.aimsWithStick; }

  endFrame() {
    this.reloadQueued = false;
    this.dashQueued = false;
    this.pauseQueued = false;
    this.switchTo = null;
    this.cycleQueued = 0;
    this.mouseJustDown = false;
  }
}

// Player and zombie entities. Rendering is vector art, no external assets.
import { WEAPONS, ZOMBIE_TYPES, BOSSES } from './data.js';
import {
  TAU, clamp, lerp, rand, randInt, chance, angleLerp, angleDiff, dist, norm, easeOutCubic,
} from './utils.js';

export class Player {
  constructor(game) {
    this.g = game;
    this.reset();
  }

  reset() {
    const w = this.g.world;
    this.x = w.w / 2;
    this.y = w.h / 2;
    this.r = 15;
    this.vx = 0;
    this.vy = 0;
    this.speed = 238;
    this.aim = -Math.PI / 2;
    this.moveAngle = -Math.PI / 2;
    this.anim = 0;
    this.walking = false;
    this.hp = 100;
    this.maxHp = 100;
    this.shield = 0;
    this.shieldTimer = 0;
    this.shieldMax = 70;
    this.invuln = 0;
    this.hurtTimer = 0;
    this.dashTimer = 0;
    this.dashCdTimer = 0;
    this.dashCdBase = 1.25;
    this.dashDir = { x: 1, y: 0 };
    this.muzzleFlash = 0;
    this.muzzleAngle = 0;
    this.rapid = 0;
    this.damagePower = 0;
    this.weaponIndex = 0;
    this.stats = {
      damage: 1,
      fireRate: 1,
      reloadSpeed: 1,
      speed: 1,
      magnet: 1,
      crit: 0,
      pierce: 0,
      dashCd: 1,
      regen: 0,
      lifesteal: 0,
      armor: 0,
      reserveMul: 1,
    };
    this.upgradeLevels = {};
    this.stepTimer = 0;
    this.dead = false;
    this.weapons = WEAPONS.map((def) => ({
      def,
      mag: def.magSize,
      reserve: def.reserve,
      maxReserve: def.reserve,
      reloading: false,
      reloadTimer: 0,
      cooldown: 0,
      lastEmpty: 0,
    }));
  }

  get weapon() { return this.weapons[this.weaponIndex]; }

  get alive() { return this.hp > 0; }

  update(dt) {
    const input = this.g.input;
    const w = this.g.world;

    // timers
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtTimer = Math.max(0, this.hurtTimer - dt);
    this.dashTimer = Math.max(0, this.dashTimer - dt);
    this.dashCdTimer = Math.max(0, this.dashCdTimer - dt);
    this.muzzleFlash = Math.max(0, this.muzzleFlash - dt);
    this.rapid = Math.max(0, this.rapid - dt);
    this.damagePower = Math.max(0, this.damagePower - dt);
    if (this.shield > 0) {
      this.shieldTimer = Math.max(0, this.shieldTimer - dt);
      if (this.shieldTimer <= 0) this.shield = 0;
    }

    // weapon switching
    if (input.switchTo !== null) this.swapWeapon(input.switchTo);
    if (input.cycleQueued) this.cycleWeapon(input.cycleQueued);

    // aim
    if (input.aimsWithStick) {
      let a = Math.atan2(input.aimStick.y, input.aimStick.x);
      a = this.g.getAimAssist(this.x, this.y, a);
      this.aim = angleLerp(this.aim, a, 1 - Math.exp(-18 * dt));
    } else {
      const m = this.g.screenToWorld(input.mouse.x, input.mouse.y);
      const target = Math.atan2(m.y - this.y, m.x - this.x);
      this.aim = angleLerp(this.aim, target, 1 - Math.exp(-26 * dt));
    }

    // movement
    const move = input.getMoveVector();
    this.walking = move.mag > 0.05;
    if (this.walking) this.moveAngle = Math.atan2(move.y, move.x);
    let speed = this.speed * this.stats.speed;

    if (this.dashTimer > 0) {
      speed *= 3.15;
      const targetVx = this.dashDir.x * speed;
      const targetVy = this.dashDir.y * speed;
      this.vx = lerp(this.vx, targetVx, 1 - Math.exp(-30 * dt));
      this.vy = lerp(this.vy, targetVy, 1 - Math.exp(-30 * dt));
      if (chance(dt * 60)) {
        this.g.spawnParticle({
          kind: 'smoke', x: this.x - this.dashDir.x * 8 + rand(-4, 4), y: this.y - this.dashDir.y * 8 + rand(-4, 4),
          vx: rand(-20, 20), vy: rand(-20, 20), life: 0.4, maxLife: 0.4, size: rand(3, 7), color: 'rgba(170,190,200,0.28)', grow: 12,
        });
      }
    } else {
      const targetVx = move.x * speed;
      const targetVy = move.y * speed;
      const accel = 1 - Math.exp(-(move.mag > 0.05 ? 16 : 11) * dt);
      this.vx = lerp(this.vx, targetVx, accel);
      this.vy = lerp(this.vy, targetVy, accel);
    }

    if (move.mag > 0.4 && this.walking && this.dashTimer <= 0) {
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = 0.22;
        this.g.spawnParticle({
          kind: 'smoke', x: this.x + rand(-5, 5), y: this.y + 5, vx: rand(-8, 8), vy: rand(2, 12),
          life: 0.35, maxLife: 0.35, size: rand(2, 4), color: 'rgba(140,150,140,0.13)', grow: 9,
        });
      }
    }

    // dash
    const canDash = this.dashCdTimer <= 0;
    if (input.dashQueued && canDash) this.startDash(move);

    this.x += this.vx * dt;
    this.y += this.vy * dt;

    // zombie body separation (prevents walking inside the horde)
    for (const z of this.g.zombies) {
      if (z.dead || z.spawnT < 0.22) continue;
      const dx = this.x - z.x;
      const dy = this.y - z.y;
      const min = this.r * 0.7 + z.r * 0.72;
      const d2 = dx * dx + dy * dy;
      if (d2 > 0.001 && d2 < min * min) {
        const d = Math.sqrt(d2);
        const push = (min - d) * 0.32;
        this.x += (dx / d) * push;
        this.y += (dy / d) * push;
      }
    }

    this.x = clamp(this.x, 54, w.w - 54);
    this.y = clamp(this.y, 54, w.h - 54);

    this.anim += (Math.hypot(this.vx, this.vy) / 60 + 2) * dt;
    if (this.stats.regen > 0 && this.hp > 0 && this.hp < this.maxHp) {
      this.hp = Math.min(this.maxHp, this.hp + this.stats.regen * dt);
    }

    // reload
    const wp = this.weapon;
    wp.cooldown = Math.max(0, wp.cooldown - dt);
    if (wp.reloading) {
      wp.reloadTimer -= dt;
      if (wp.reloadTimer <= 0) this.finishReload();
    }

    if (input.reloadQueued) this.startReload();

    // firing
    if (input.firing) {
      if (!wp.reloading && wp.cooldown <= 0 && wp.mag > 0) this.shoot();
      else if (!wp.reloading && wp.mag <= 0) {
        if (wp.reserve > 0) this.startReload();
        else if (this.g.time - wp.lastEmpty > 0.35) {
          wp.lastEmpty = this.g.time;
          this.g.sound.empty();
          this.g.toast('OUT OF AMMO — FIND A CRATE', 'warn');
        }
      }
    }

    if (this.dashCdTimer > 0 && this.dashTimer <= 0) {
      const w2 = this.dashCdTimer / (this.dashCdBase * this.stats.dashCd);
      this.g.dashCharge = 1 - clamp(w2, 0, 1);
    } else this.g.dashCharge = 1;
  }

  startDash(move) {
    const useMove = move.mag > 0.1;
    this.dashDir = useMove
      ? { x: move.x, y: move.y }
      : { x: Math.cos(this.aim), y: Math.sin(this.aim) };
    this.dashTimer = 0.16;
    this.invuln = Math.max(this.invuln, 0.3);
    this.dashCdTimer = this.dashCdBase * this.stats.dashCd;
    this.g.sound.dash();
    this.g.shake(2.5);
    this.g.ring(this.x, this.y, 34, 'rgba(180,220,230,0.35)', 0.35, 110);
    this.g.burstSparks(this.x, this.y, 6, '#b9d4dd', 90, 0.3);
  }

  swapWeapon(index) {
    index = clamp(index, 0, this.weapons.length - 1);
    if (index === this.weaponIndex) return;
    const cur = this.weapon;
    if (cur.reloading) { cur.reloading = false; cur.reloadTimer = 0; }
    this.weaponIndex = index;
    this.weapon.cooldown = Math.max(this.weapon.cooldown, 0.16);
    this.g.sound.swap();
    this.g.toast(this.weapon.def.name + ' READY', '');
  }

  cycleWeapon(delta) {
    const len = this.weapons.length;
    this.swapWeapon(((this.weaponIndex + delta) % len + len) % len);
  }

  startReload(silent = false) {
    const wp = this.weapon;
    if (wp.reloading || wp.mag >= wp.def.magSize) return;
    if (wp.reserve <= 0) {
      if (!silent) {
        this.g.sound.empty();
        this.g.toast('NO RESERVE AMMO — SCAVENGE CRATES', 'warn');
      }
      return;
    }
    wp.reloading = true;
    wp.reloadTimer = wp.def.reload / this.stats.reloadSpeed;
    if (!silent) this.g.sound.reload(0);
  }

  finishReload() {
    const wp = this.weapon;
    const need = wp.def.magSize - wp.mag;
    if (need <= 0) { wp.reloading = false; return; }
    if (wp.reserve === Infinity) {
      wp.mag = wp.def.magSize;
    } else {
      const take = Math.min(need, wp.reserve);
      wp.mag += take;
      wp.reserve -= take;
      wp.maxReserve = Math.round(wp.def.reserve * this.stats.reserveMul);
    }
    wp.reloading = false;
    this.g.sound.reload(1);
  }

  shoot() {
    const wp = this.weapon;
    const def = wp.def;
    if (wp.mag <= 0 || wp.reloading) return;
    wp.mag -= 1;
    const rapidMul = this.rapid > 0 ? 0.48 : 1;
    wp.cooldown = def.fireInterval / this.stats.fireRate * rapidMul;

    const movingSpread = Math.min(1.9, 1 + Math.hypot(this.vx, this.vy) / 420);
    const dmgMul = this.stats.damage * (this.damagePower > 0 ? 1.65 : 1);
    const muzzleX = this.x + Math.cos(this.aim) * (this.r + 12);
    const muzzleY = this.y + Math.sin(this.aim) * (this.r + 12);
    const pellets = def.pellets;

    for (let i = 0; i < pellets; i++) {
      let angle;
      if (pellets > 1) {
        const t = pellets === 1 ? 0 : i / (pellets - 1) - 0.5;
        angle = this.aim + t * def.spread * 2 + rand(-0.022, 0.022);
      } else {
        angle = this.aim + rand(-def.spread, def.spread) * movingSpread;
      }
      const crit = chance(this.stats.crit);
      const damage = def.damage * dmgMul * (crit ? 2 : 1);
      this.g.spawnBullet({
        x: muzzleX,
        y: muzzleY,
        angle,
        speed: def.speed * rand(0.97, 1.03),
        damage,
        crit,
        pierce: def.pierce + Math.floor(this.stats.pierce),
        knockback: def.knockback,
        color: def.tracer,
        weapon: def.id,
      });
    }

    // recoil, muzzle effects, sound
    this.vx -= Math.cos(this.aim) * def.recoil;
    this.vy -= Math.sin(this.aim) * def.recoil;
    this.muzzleFlash = 0.075;
    this.muzzleAngle = this.aim;
    this.g.shake(def.shake);
    this.g.crosshairKick = 1;
    const spreadParticles = def.id === 'shotgun' ? 9 : 4;
    for (let i = 0; i < spreadParticles; i++) {
      const a = this.aim + rand(-0.22, 0.22);
      const sp = rand(80, 320);
      this.g.spawnParticle({
        kind: 'spark', x: muzzleX, y: muzzleY, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: rand(0.06, 0.18), maxLife: 0.18, size: rand(1, 2.4), color: def.id === 'shotgun' ? '#ffc98a' : '#ffe6a8', drag: 5,
      });
    }
    this.g.spawnParticle({
      kind: 'smoke', x: muzzleX, y: muzzleY, vx: Math.cos(this.aim) * 40, vy: Math.sin(this.aim) * 40,
      life: 0.35, maxLife: 0.35, size: rand(3, 6), color: 'rgba(200,190,170,0.16)', grow: 34,
    });
    // shell casing
    const casingA = this.aim + Math.PI / 2 + rand(-0.3, 0.3);
    this.g.spawnParticle({
      kind: 'casing', x: this.x + Math.cos(this.aim) * 10, y: this.y + Math.sin(this.aim) * 10,
      vx: Math.cos(casingA) * rand(60, 130), vy: Math.sin(casingA) * rand(60, 130) - 20,
      life: 1.6, maxLife: 1.6, size: 2.4, color: '#dcb45a', rot: rand(0, TAU), rotSpeed: rand(-12, 12), drag: 5,
    });
    this.g.sound.shoot(def.id);
    this.g.muzzleLight = { x: muzzleX, y: muzzleY, angle: this.aim, life: 0.075, max: 0.075, color: def.color };
    this.g.lastShotWeapon = def.id;
  }

  takeDamage(amount, srcX = null, srcY = null, opts = {}) {
    if (this.hp <= 0 || this.invuln > 0 || this.dashTimer > 0 || this.g.mode !== 'playing') return false;
    let dmg = amount;
    if (this.shield > 0) {
      const absorbed = Math.min(this.shield, dmg);
      this.shield -= absorbed;
      dmg -= absorbed;
      this.shieldTimer = Math.max(this.shieldTimer, 1.5);
      this.g.sound.shieldHit();
      this.g.ring(this.x, this.y, this.r + 12, 'rgba(90,215,255,0.65)', 0.4, 90);
      this.g.shake(4);
      if (dmg <= 0) {
        this.invuln = 0.35;
        return true;
      }
    }
    dmg *= (1 - this.stats.armor);
    this.hp = Math.max(0, this.hp - dmg);
    this.invuln = 0.68;
    this.hurtTimer = 0.35;
    this.g.damageFlash = Math.min(1, this.g.damageFlash + 0.75);
    this.g.shake(8 + dmg * 0.22);
    this.g.sound.hurt();
    this.g.floatText(this.x, this.y - 24, '-' + Math.round(dmg), '#ff5c5f', 17);
    this.g.burstBlood(this.x, this.y, 7, '#a51e25', 160);
    this.g.hitDirection = srcX !== null ? Math.atan2(this.y - srcY, this.x - srcX) : rand(0, TAU);
    if (srcX !== null) {
      const n = norm(this.x - srcX, this.y - srcY);
      this.vx += n.x * 130;
      this.vy += n.y * 130;
    }
    if (this.hp <= 0) this.g.gameOver();
    return true;
  }

  heal(amount) {
    const before = this.hp;
    this.hp = Math.min(this.maxHp, this.hp + amount);
    return this.hp - before;
  }

  addShield(amount, time = 12) {
    this.shieldMax = Math.max(this.shieldMax, amount);
    this.shield = Math.min(this.shieldMax, this.shield + amount);
    this.shieldTimer = Math.max(this.shieldTimer, time);
  }

  addAmmo(frac = 0.35) {
    let added = 0;
    for (const w of this.weapons) {
      if (w.reserve === Infinity) continue;
      w.maxReserve = Math.round(w.def.reserve * this.stats.reserveMul);
      const before = w.reserve;
      w.reserve = Math.min(w.maxReserve, w.reserve + Math.ceil(w.maxReserve * frac));
      added += w.reserve - before;
    }
    return added;
  }

  refillReserves() {
    for (const w of this.weapons) {
      if (w.reserve === Infinity) continue;
      w.maxReserve = Math.round(w.def.reserve * this.stats.reserveMul);
      w.reserve = w.maxReserve;
    }
  }

  render(ctx, time) {
    const blink = this.invuln > 0 && Math.floor(time * 22) % 2 === 0 ? 0.45 : 1;
    ctx.save();
    ctx.translate(this.x, this.y);

    // shadow
    ctx.fillStyle = 'rgba(0,0,0,0.42)';
    ctx.beginPath();
    ctx.ellipse(0, 7, this.r * 1.25, this.r * 0.72, 0, 0, TAU);
    ctx.fill();

    // legs
    ctx.save();
    ctx.rotate(this.moveAngle);
    const stride = this.walking ? Math.sin(this.anim * 7) * 5 : 0;
    ctx.strokeStyle = '#22282b';
    ctx.lineWidth = 7;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-3, -6);
    ctx.lineTo(-7 + stride, -10);
    ctx.moveTo(-3, 6);
    ctx.lineTo(-7 - stride, 10);
    ctx.stroke();
    ctx.strokeStyle = '#101315';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(-6 + stride, -10);
    ctx.lineTo(-8 + stride, -13);
    ctx.moveTo(-6 - stride, 10);
    ctx.lineTo(-8 - stride, 13);
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.rotate(this.aim);
    ctx.globalAlpha = blink;

    // backpack
    ctx.fillStyle = '#202a26';
    ctx.beginPath();
    ctx.ellipse(-10, 0, 7, 10, 0, 0, TAU);
    ctx.fill();

    // torso
    ctx.fillStyle = '#2f3d33';
    ctx.beginPath();
    ctx.ellipse(0, 0, 14, 12.5, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#182019';
    ctx.lineWidth = 2;
    ctx.stroke();
    // vest highlight
    ctx.fillStyle = '#44563f';
    ctx.beginPath();
    ctx.ellipse(2, 0, 8.5, 8.5, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(190,210,160,0.18)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(2, 0, 8.5, -1.1, 1.1);
    ctx.stroke();

    // shoulders
    ctx.fillStyle = '#26332b';
    ctx.beginPath();
    ctx.ellipse(1, -10, 5, 4, -0.4, 0, TAU);
    ctx.ellipse(1, 10, 5, 4, 0.4, 0, TAU);
    ctx.fill();

    // gun (extends forward)
    const kind = this.weapon.def.id;
    if (kind === 'shotgun') {
      ctx.fillStyle = '#1b1c1e';
      ctx.fillRect(12, -2.6, 25, 5.2);
      ctx.fillStyle = '#3a2f25';
      ctx.fillRect(5, -4.5, 10, 9);
      ctx.fillStyle = '#5c4a36';
      ctx.fillRect(20, 2, 7, 4);
      ctx.fillStyle = '#c9a86a';
      ctx.fillRect(30, -1.2, 6, 2.4);
    } else if (kind === 'smg') {
      ctx.fillStyle = '#1c2024';
      ctx.fillRect(12, -3.5, 21, 7);
      ctx.fillStyle = '#2a3035';
      ctx.fillRect(14, 2.5, 7, 9);
      ctx.fillStyle = '#4cc9f0';
      ctx.fillRect(22, -1, 6, 2);
      ctx.fillStyle = '#0e1114';
      ctx.fillRect(31, -1.4, 5, 2.8);
    } else {
      ctx.fillStyle = '#1c1f22';
      ctx.fillRect(13, -2.3, 13, 4.6);
      ctx.fillStyle = '#2b3135';
      ctx.fillRect(12, 2, 6, 8);
      ctx.fillStyle = '#c9a86a';
      ctx.fillRect(24, -1, 4, 2);
    }

    // arms
    ctx.strokeStyle = '#6d7d58';
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(1, -8);
    ctx.lineTo(10, -5);
    ctx.lineTo(15, 0.5);
    ctx.stroke();
    ctx.strokeStyle = '#5c6b4b';
    ctx.beginPath();
    ctx.moveTo(1, 8);
    ctx.lineTo(9, 5);
    ctx.lineTo(14, 1.5);
    ctx.stroke();

    // head / cap
    ctx.fillStyle = '#b28c67';
    ctx.beginPath();
    ctx.arc(6, 0, 7.2, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#7b5f45';
    ctx.lineWidth = 1.4;
    ctx.stroke();
    ctx.fillStyle = '#31402f';
    ctx.beginPath();
    ctx.arc(4.5, 0, 6.4, Math.PI * 0.45, Math.PI * 1.55);
    ctx.fill();
    ctx.fillStyle = '#26331f';
    ctx.beginPath();
    ctx.ellipse(10.5, 0, 3.4, 4.6, 0, 0, TAU);
    ctx.fill();
    // flash light glint
    ctx.fillStyle = 'rgba(255,240,180,0.9)';
    ctx.beginPath();
    ctx.arc(12.8, 0, 1.6, 0, TAU);
    ctx.fill();

    // muzzle flash
    if (this.muzzleFlash > 0) {
      const f = this.muzzleFlash / 0.075;
      const mx = kind === 'shotgun' ? 37 : kind === 'smg' ? 36 : 28;
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = `rgba(255,220,140,${0.85 * f})`;
      ctx.beginPath();
      ctx.moveTo(mx, 0);
      ctx.lineTo(mx + 12 * f, -6 * f);
      ctx.lineTo(mx + 20 * f, 0);
      ctx.lineTo(mx + 12 * f, 6 * f);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = `rgba(255,255,240,${0.9 * f})`;
      ctx.beginPath();
      ctx.arc(mx, 0, 4.5 * f, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    }

    ctx.restore();
    ctx.globalAlpha = 1;

    // shield bubble
    if (this.shield > 0) {
      const ratio = this.shield / this.shieldMax;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const grad = ctx.createRadialGradient(0, 0, this.r * 0.5, 0, 0, this.r + 17);
      grad.addColorStop(0, 'rgba(76,201,240,0)');
      grad.addColorStop(0.7, `rgba(76,201,240,${0.08 + ratio * 0.08})`);
      grad.addColorStop(1, `rgba(120,230,255,${0.24 + ratio * 0.24})`);
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, this.r + 17, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = `rgba(140,235,255,${0.35 + ratio * 0.35})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(0, 0, this.r + 16, time * 1.4, time * 1.4 + Math.PI * 1.45);
      ctx.stroke();
      ctx.restore();
    }

    if (this.dashCdTimer <= 0) {
      ctx.strokeStyle = 'rgba(255,183,3,0.22)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(0, 0, this.r + 7, 0, TAU);
      ctx.stroke();
    }

    ctx.restore();
  }
}

export class Zombie {
  constructor(game, type, x, y, opts = {}) {
    this.g = game;
    this.type = type;
    this.isBoss = type === 'boss';
    if (this.isBoss) {
      this.def = {
        id: 'boss', name: 'BOSS', hp: 1500, speed: 55, radius: 54, damage: 24,
        attackCd: 1.0, coins: [40, 50], score: 600, body: '#5a1f22', bodyDark: '#2a0d0f',
        skin: '#b13a3f', accent: '#ff5c5f', eye: '#ffe066', blood: '#4a0f12', ranged: false,
      };
      this.bossIndex = opts.bossIndex || 1;
      const b = BOSSES[(this.bossIndex - 1) % BOSSES.length];
      this.bossColors = b;
      this.name = b.name;
    } else {
      this.def = ZOMBIE_TYPES[type];
    }
    this.x = x;
    this.y = y;
    this.spawnT = 0;
    this.r = this.def.radius * (this.isBoss ? 1 : rand(0.92, 1.08));
    const hpMul = game.difficulty.hp;
    this.maxHp = Math.round(this.def.hp * hpMul * (this.isBoss ? (1 + (this.bossIndex - 1) * 0.85) * 1.6 : 1));
    this.hp = this.maxHp;
    this.speed = this.def.speed * game.difficulty.speed * (this.isBoss ? 1 : rand(0.92, 1.08));
    this.damage = this.def.damage * game.difficulty.damage;
    this.vx = 0;
    this.vy = 0;
    this.angle = rand(0, TAU);
    this.anim = rand(0, TAU);
    this.hitFlash = 0;
    this.attackCd = rand(0.3, 0.8);
    this.contactCd = 0;
    this.lungeCd = rand(0.6, 2);
    this.lungeTimer = 0;
    this.fireCd = rand(1.2, 2.6);
    this.pulseCd = rand(1.5, 3.5);
    this.windup = 0;
    this.windupKind = null;
    this.attackAnim = 0;
    this.buffTimer = 0;
    this.slowTimer = 0;
    this.dead = false;
    this.lastHitDir = 0;
    this.state = 'chase';
    this.stateTimer = 0;
    this.bossAtkCd = 2.2;
    this.chargeAngle = 0;
    this.chargeHit = false;
    this.enraged = false;
    this.summonCount = 0;
    this.growlTimer = rand(2, 7);
  }

  get frozen() { return this.g.freeze > 0; }

  update(dt) {
    this.spawnT += dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.contactCd = Math.max(0, this.contactCd - dt);
    this.lungeCd = Math.max(0, this.lungeCd - dt);
    this.lungeTimer = Math.max(0, this.lungeTimer - dt);
    this.fireCd = Math.max(0, this.fireCd - dt);
    this.pulseCd = Math.max(0, this.pulseCd - dt);
    this.attackAnim = Math.max(0, this.attackAnim - dt);
    this.buffTimer = Math.max(0, this.buffTimer - dt);
    this.slowTimer = Math.max(0, this.slowTimer - dt);
    this.growlTimer -= dt;
    if (this.growlTimer <= 0) {
      this.growlTimer = rand(5, 11);
      if (this.g.camVisible(this.x, this.y, 300)) this.g.sound.growl(this.isBoss ? 0.5 : 1);
    }

    if (this.spawnT < 0.3 || this.dead) return;

    const p = this.g.player;
    const dx = p.x - this.x;
    const dy = p.y - this.y;
    const d = Math.hypot(dx, dy) || 0.001;
    const nx = dx / d;
    const ny = dy / d;

    let speed = this.speed;
    if (this.frozen) speed *= this.isBoss ? 0.6 : 0.34;
    if (this.slowTimer > 0) speed *= 0.55;
    if (this.buffTimer > 0) speed *= 1.35;
    if (this.isBoss) {
      this.updateBoss(dt, d, nx, ny, speed);
      return;
    }

    // Face travel / player
    if (this.windup <= 0) {
      this.angle = angleLerp(this.angle, Math.atan2(dy, dx), 1 - Math.exp(-7 * dt));
    }

    let vx = 0;
    let vy = 0;
    let animSpeed = 1;

    if (this.type === 'spitter') {
      const pref = this.def.preferredRange;
      if (d < pref - 70) {
        vx = -nx * speed;
        vy = -ny * speed;
        this.angle = angleLerp(this.angle, Math.atan2(dy, dx), 1 - Math.exp(-5 * dt));
      } else if (d > pref + 70) {
        vx = nx * speed;
        vy = ny * speed;
      } else {
        const strafe = Math.sin(this.g.time * 0.9 + this.anim) * speed * 0.55;
        vx = -ny * strafe;
        vy = nx * strafe;
      }
      if (this.fireCd <= 0 && d < 560 && this.windup <= 0) {
        this.windup = 0.42;
        this.windupKind = 'spit';
        this.fireCd = this.def.attackCd * rand(0.85, 1.2);
      }
      animSpeed = 0.7;
    } else if (this.type === 'brute') {
      vx = nx * speed;
      vy = ny * speed;
      animSpeed = 0.6;
      if (d < 130 && this.attackCd <= 0 && this.windup <= 0) {
        this.windup = 0.62;
        this.windupKind = 'slam';
        this.attackCd = this.def.attackCd + 1.1;
        this.angle = Math.atan2(dy, dx);
        this.g.ring(this.x, this.y, 100, 'rgba(229,56,59,0.34)', 0.62, 0);
        this.g.sound.growl(0.6);
      }
      if (this.windup > 0) { vx = 0; vy = 0; }
    } else if (this.type === 'runner') {
      vx = nx * speed;
      vy = ny * speed;
      animSpeed = 1.6;
      if (this.lungeCd <= 0 && d > 70 && d < 250) {
        this.lungeCd = rand(2.8, 4.2);
        this.lungeTimer = 0.33;
        this.angle = Math.atan2(dy, dx);
        this.g.burstSparks(this.x, this.y, 4, '#d8cba8', 70, 0.25);
      }
      if (this.lungeTimer > 0) {
        vx *= 2.8;
        vy *= 2.8;
        this.g.spawnParticle({
          kind: 'smoke', x: this.x, y: this.y + 3, vx: -vx * 0.05, vy: -vy * 0.05,
          life: 0.28, maxLife: 0.28, size: 3, color: 'rgba(170,160,140,0.14)', grow: 7,
        });
      }
    } else if (this.type === 'screamer') {
      vx = nx * speed * 0.85;
      vy = ny * speed * 0.85;
      if (this.pulseCd <= 0) {
        this.pulseCd = 4.2;
        this.g.screamerPulse(this);
      }
      animSpeed = 1.1;
    } else {
      vx = nx * speed;
      vy = ny * speed;
      animSpeed = 1;
      if (this.type === 'walker' && this.g.time % 7 < dt) {
        vx *= 0.4;
        vy *= 0.4;
      }
    }

    // windup handling
    if (this.windup > 0) {
      this.windup -= dt;
      vx = 0;
      vy = 0;
      if (this.windupKind === 'slam') {
        this.g.spawnParticle({
          kind: 'smoke', x: this.x + rand(-20, 20), y: this.y + 8, vx: rand(-10, 10), vy: rand(-4, 2),
          life: 0.3, maxLife: 0.3, size: rand(4, 8), color: 'rgba(120,110,90,0.2)', grow: 16,
        });
      }
      if (this.windup <= 0) this.resolveWindup(d);
    }

    // separation from other zombies
    let sx = 0;
    let sy = 0;
    const zombies = this.g.zombies;
    for (let i = 0; i < zombies.length; i++) {
      const o = zombies[i];
      if (o === this || o.dead) continue;
      const ox = this.x - o.x;
      const oy = this.y - o.y;
      const min = (this.r + o.r) * 0.82;
      const od2 = ox * ox + oy * oy;
      if (od2 > 0.001 && od2 < min * min) {
        const od = Math.sqrt(od2);
        const force = (min - od) / min;
        sx += (ox / od) * force;
        sy += (oy / od) * force;
      }
    }
    vx += sx * speed * 0.9;
    vy += sy * speed * 0.9;

    // avoid stacking directly on the player
    if (d < this.r + p.r * 0.65) {
      vx -= nx * speed * 0.8;
      vy -= ny * speed * 0.8;
    }

    const accel = 1 - Math.exp(-(this.isBoss ? 4 : 9) * dt);
    this.vx = lerp(this.vx, vx, accel);
    this.vy = lerp(this.vy, vy, accel);
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.anim += dt * animSpeed * (1 + Math.hypot(this.vx, this.vy) / 300);

    // melee
    if (d < this.r + p.r + 5 && this.attackCd <= 0 && this.windup <= 0) {
      if (this.type === 'brute') {
        // handled by windup, do nothing
      } else {
        this.attackCd = this.def.attackCd * rand(0.9, 1.15);
        this.attackAnim = 0.22;
        p.takeDamage(this.damage * (this.buffTimer > 0 ? 1.2 : 1), this.x, this.y);
        this.g.burstBlood(p.x, p.y, 2, '#7a1218', 70);
      }
    }

    const w = this.g.world;
    this.x = clamp(this.x, 40, w.w - 40);
    this.y = clamp(this.y, 40, w.h - 40);
  }

  resolveWindup(d) {
    const p = this.g.player;
    if (this.windupKind === 'slam') {
      this.g.sound.slam();
      this.g.shake(13);
      this.g.ring(this.x, this.y, 100, 'rgba(255,120,90,0.65)', 0.55, 420);
      this.g.dustBurst(this.x, this.y, 22, '#6b5d4a');
      if (d < 122) p.takeDamage(this.damage * 1.25, this.x, this.y);
    } else if (this.windupKind === 'spit') {
      const angle = Math.atan2(p.y - this.y, p.x - this.x) + rand(-0.05, 0.05);
      this.g.spawnAcid(this.x + Math.cos(angle) * this.r, this.y + Math.sin(angle) * this.r, angle, this.damage, 420);
      this.g.sound.spit();
      this.attackAnim = 0.3;
    }
    this.windupKind = null;
  }

  updateBoss(dt, d, nx, ny, speed) {
    const p = this.g.player;
    if (!this.enraged && this.hp < this.maxHp * 0.35) {
      this.enraged = true;
      this.speed *= 1.22;
      this.g.toast(`${this.name} IS ENRAGED`, 'danger');
      this.g.sound.boss();
      this.g.shake(10);
      this.g.ring(this.x, this.y, this.r + 40, 'rgba(255,60,60,0.8)', 0.8, 380);
    }

    const face = Math.atan2(p.y - this.y, p.x - this.x);
    if (this.state === 'chase') {
      if (this.windup <= 0) this.angle = angleLerp(this.angle, face, 1 - Math.exp(-5 * dt));
      this.vx = lerp(this.vx, nx * speed, 1 - Math.exp(-4 * dt));
      this.vy = lerp(this.vy, ny * speed, 1 - Math.exp(-4 * dt));
      this.x += this.vx * dt;
      this.y += this.vy * dt;
      this.anim += dt * (1 + Math.hypot(this.vx, this.vy) / 300);
      this.bossAtkCd -= dt;
      if (d < this.r + p.r + 6 && this.contactCd <= 0) {
        this.contactCd = 0.85;
        p.takeDamage(this.damage, this.x, this.y);
        this.attackAnim = 0.3;
      }
      if (this.bossAtkCd <= 0) this.chooseBossAttack(d);
    } else if (this.state === 'chargeWind') {
      this.stateTimer -= dt;
      this.angle = angleLerp(this.angle, face, 1 - Math.exp(-9 * dt));
      this.chargeAngle = this.angle;
      this.vx *= 0.85;
      this.vy *= 0.85;
      this.g.spawnParticle({
        kind: 'ember', x: this.x + rand(-this.r, this.r), y: this.y + rand(-this.r, this.r),
        vx: rand(-20, 20), vy: rand(-30, 0), life: 0.4, maxLife: 0.4, size: rand(2, 4), color: 'rgba(255,120,90,0.7)',
      });
      if (this.stateTimer <= 0) {
        this.state = 'charge';
        this.stateTimer = 0.55;
        this.chargeHit = false;
        this.vx = Math.cos(this.chargeAngle) * 760;
        this.vy = Math.sin(this.chargeAngle) * 760;
        this.g.shake(6);
        this.g.sound.growl(0.4);
      }
    } else if (this.state === 'charge') {
      this.stateTimer -= dt;
      this.x += this.vx * dt;
      this.y += this.vy * dt;
      this.anim += dt * 6;
      if (chance(dt * 50)) {
        this.g.dustBurst(this.x - Math.cos(this.chargeAngle) * 20, this.y - Math.sin(this.chargeAngle) * 20, 3, '#675a48');
      }
      if (!this.chargeHit && d < this.r + p.r + 12) {
        this.chargeHit = true;
        p.takeDamage(this.damage * 1.35, this.x, this.y);
        this.g.shake(14);
      }
      if (this.stateTimer <= 0) {
        this.state = 'recover';
        this.stateTimer = this.enraged ? 0.55 : 0.9;
        this.bossAtkCd = this.enraged ? 1.6 : 2.3;
      }
    } else if (this.state === 'slamWind') {
      this.stateTimer -= dt;
      this.vx *= 0.8;
      this.vy *= 0.8;
      if (chance(dt * 25)) this.g.dustBurst(this.x, this.y + 10, 2, '#5b5044');
      if (this.stateTimer <= 0) {
        this.state = 'recover';
        this.stateTimer = 0.95;
        this.bossAtkCd = this.enraged ? 1.7 : 2.5;
        this.g.sound.slam();
        this.g.shake(20);
        this.g.spawnShockwave(this.x, this.y, 300, this.damage * 1.5, '#ff6b5c');
        this.g.dustBurst(this.x, this.y, 30, '#6b5d4a');
        if (d < 310) p.takeDamage(this.damage * 1.2, this.x, this.y);
      }
    } else if (this.state === 'summon') {
      this.stateTimer -= dt;
      if (this.stateTimer <= 0) {
        const count = this.enraged ? 6 : 4;
        for (let i = 0; i < count; i++) {
          const a = (i / count) * TAU + rand(-0.2, 0.2);
          const r = this.r + rand(30, 70);
          const types = this.g.availableZombieTypes().filter((t) => t !== 'brute');
          const t = types.length ? types[randInt(0, types.length - 1)] : 'walker';
          this.g.spawnZombie(t, this.x + Math.cos(a) * r, this.y + Math.sin(a) * r, { noWarning: true });
          this.g.burstBlood(this.x + Math.cos(a) * r, this.y + Math.sin(a) * r, 4, '#3a0d0f', 100);
        }
        this.g.toast(`${this.name} CALLS THE HORDE`, 'danger');
        this.g.sound.boss();
        this.state = 'recover';
        this.stateTimer = 0.9;
        this.bossAtkCd = this.enraged ? 1.6 : 2.4;
      }
    } else if (this.state === 'volley') {
      this.stateTimer -= dt;
      if (this.stateTimer <= 0) {
        const base = Math.atan2(p.y - this.y, p.x - this.x);
        const count = this.enraged ? 9 : 6;
        for (let i = 0; i < count; i++) {
          const a = base + (i - (count - 1) / 2) * 0.16;
          this.g.spawnAcid(this.x + Math.cos(a) * this.r, this.y + Math.sin(a) * this.r, a, this.damage * 0.7, 470);
        }
        this.g.sound.spit();
        this.state = 'recover';
        this.stateTimer = 0.75;
        this.bossAtkCd = this.enraged ? 1.5 : 2.2;
      }
    } else if (this.state === 'recover') {
      this.stateTimer -= dt;
      this.vx *= 0.86;
      this.vy *= 0.86;
      if (this.stateTimer <= 0) this.state = 'chase';
    }

    const w = this.g.world;
    this.x = clamp(this.x, 54, w.w - 54);
    this.y = clamp(this.y, 54, w.h - 54);
  }

  chooseBossAttack(d) {
    const roll = Math.random();
    if (d < 210) {
      if (roll < 0.45) this.beginSlam();
      else if (roll < 0.7) this.beginSummon();
      else if (roll < 0.88) this.beginVolley();
      else this.beginCharge();
    } else {
      if (roll < 0.44) this.beginCharge();
      else if (roll < 0.66) this.beginSummon();
      else if (roll < 0.9) this.beginVolley();
      else this.beginSlam();
    }
  }

  beginCharge() {
    this.state = 'chargeWind';
    this.stateTimer = this.enraged ? 0.6 : 0.9;
    this.g.sound.growl(0.35);
  }

  beginSlam() {
    this.state = 'slamWind';
    this.stateTimer = this.enraged ? 0.7 : 1.0;
    this.g.sound.growl(0.4);
  }

  beginSummon() {
    this.state = 'summon';
    this.stateTimer = 0.85;
  }

  beginVolley() {
    this.state = 'volley';
    this.stateTimer = 0.7;
  }

  takeDamage(amount, opts = {}) {
    if (this.dead) return;
    this.hp -= amount;
    this.hitFlash = 0.1;
    if (opts.crit) this.hitFlash = 0.16;
    if (this.hp <= 0) {
      this.hp = 0;
      this.dead = true;
      this.g.killZombie(this, opts);
    }
  }

  drawTelegraph(ctx) {
    if (!this.isBoss) return;
    const pulse = 0.5 + Math.sin(this.g.time * 12) * 0.2;
    if (this.state === 'chargeWind') {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.chargeAngle);
      const grad = ctx.createLinearGradient(0, 0, 780, 0);
      grad.addColorStop(0, `rgba(255,55,55,${0.3 * pulse + 0.12})`);
      grad.addColorStop(0.8, 'rgba(255,55,55,0.1)');
      grad.addColorStop(1, 'rgba(255,55,55,0)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, -this.r * 0.6, 780, this.r * 1.2);
      ctx.strokeStyle = `rgba(255,90,90,${pulse})`;
      ctx.lineWidth = 2;
      ctx.setLineDash([12, 10]);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(780, 0);
      ctx.stroke();
      ctx.restore();
    } else if (this.state === 'slamWind') {
      ctx.save();
      ctx.strokeStyle = `rgba(255,80,60,${0.35 + pulse * 0.4})`;
      ctx.fillStyle = `rgba(255,60,40,${0.05 + pulse * 0.05})`;
      ctx.lineWidth = 3;
      ctx.setLineDash([14, 9]);
      ctx.beginPath();
      ctx.arc(this.x, this.y, 300, 0, TAU);
      ctx.fill();
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
  }

  render(ctx, time) {
    if (this.spawnT < 0.3) {
      // rise-from-ground spawn effect drawn by the warning; keep entity mostly hidden
    }
    const appear = clamp(this.spawnT / 0.3, 0, 1);
    const scale = this.isBoss ? easeOutCubic(appear) : lerp(0.55, 1, easeOutCubic(appear));
    const def = this.def;
    const bodyCol = this.isBoss ? this.bossColors.body : def.body;
    const darkCol = this.isBoss ? this.bossColors.dark : def.bodyDark;
    const skinCol = this.isBoss ? this.bossColors.skin : def.skin;
    const accent = this.isBoss ? this.bossColors.accent : def.accent;

    // shadow
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.globalAlpha = appear;
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(0, this.r * 0.5, this.r * 1.15, this.r * 0.62, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.scale(scale, scale);
    ctx.rotate(this.angle);
    ctx.globalAlpha = appear;
    const r = this.r;
    const wobble = Math.sin(this.anim * 6) * 0.12;

    // legs
    ctx.strokeStyle = darkCol;
    ctx.lineWidth = Math.max(4, r * 0.24);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-r * 0.3, -r * 0.34);
    ctx.lineTo(-r * 0.72, -r * 0.6 + Math.sin(this.anim * 7) * r * 0.16);
    ctx.moveTo(-r * 0.3, r * 0.34);
    ctx.lineTo(-r * 0.72, r * 0.6 - Math.sin(this.anim * 7) * r * 0.16);
    ctx.stroke();

    // arms reaching
    const reach = this.attackAnim > 0 ? 1.22 : 1;
    ctx.strokeStyle = skinCol;
    ctx.lineWidth = Math.max(3.5, r * 0.2);
    ctx.beginPath();
    ctx.moveTo(r * 0.1, -r * 0.55);
    ctx.lineTo(r * 0.92 * reach, -r * 0.68 - wobble * r);
    ctx.lineTo(r * 1.18 * reach, -r * 0.36);
    ctx.moveTo(r * 0.1, r * 0.55);
    ctx.lineTo(r * 0.92 * reach, r * 0.68 - wobble * r);
    ctx.lineTo(r * 1.18 * reach, r * 0.36);
    ctx.stroke();
    // hands
    ctx.fillStyle = skinCol;
    ctx.beginPath();
    ctx.arc(r * 1.2 * reach, -r * 0.34, r * 0.16, 0, TAU);
    ctx.arc(r * 1.2 * reach, r * 0.34, r * 0.16, 0, TAU);
    ctx.fill();

    // body
    ctx.fillStyle = bodyCol;
    ctx.beginPath();
    if (this.type === 'runner') {
      ctx.ellipse(0, 0, r * 0.78, r * 0.58, 0, 0, TAU);
    } else if (this.type === 'brute' || this.isBoss) {
      ctx.ellipse(0, 0, r * 0.98, r * 0.88, 0, 0, TAU);
    } else {
      ctx.ellipse(0, 0, r * 0.84, r * 0.72, 0, 0, TAU);
    }
    ctx.fill();
    ctx.strokeStyle = darkCol;
    ctx.lineWidth = 2;
    ctx.stroke();

    // torn shirt / ribs
    ctx.strokeStyle = darkCol;
    ctx.lineWidth = Math.max(1, r * 0.07);
    ctx.globalAlpha = appear * 0.7;
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.52, -0.8, 0.3);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-r * 0.25, -r * 0.4);
    ctx.lineTo(-r * 0.4, -r * 0.15);
    ctx.stroke();
    ctx.globalAlpha = appear;

    // shoulders spikes for brute/boss
    if (this.type === 'brute' || this.isBoss) {
      ctx.fillStyle = accent;
      ctx.globalAlpha = appear * 0.5;
      for (let i = 0; i < 4; i++) {
        const a = -0.9 + i * 0.6;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * r * 0.72, Math.sin(a) * r * 0.72);
        ctx.lineTo(Math.cos(a) * r * 1.12, Math.sin(a) * r * 1.12);
        ctx.lineTo(Math.cos(a + 0.18) * r * 0.7, Math.sin(a + 0.18) * r * 0.7);
        ctx.fill();
      }
      ctx.globalAlpha = appear;
    }

    // spitter sac
    if (this.type === 'spitter') {
      ctx.fillStyle = 'rgba(157,255,77,0.5)';
      ctx.beginPath();
      ctx.ellipse(-r * 0.1, 0, r * 0.38, r * 0.5, 0, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = 'rgba(190,255,120,0.55)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    // screamer ribs / open mouth
    if (this.type === 'screamer') {
      ctx.fillStyle = accent;
      ctx.globalAlpha = appear * 0.55;
      ctx.beginPath();
      ctx.arc(0, 0, r * 0.3 + Math.sin(time * 8) * r * 0.04, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = appear;
    }

    // head
    const hx = r * 0.62;
    ctx.fillStyle = skinCol;
    ctx.beginPath();
    ctx.arc(hx, 0, r * 0.48, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = darkCol;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // hair patch at back
    ctx.fillStyle = darkCol;
    ctx.beginPath();
    ctx.arc(hx - r * 0.16, 0, r * 0.38, Math.PI * 0.52, Math.PI * 1.48);
    ctx.fill();
    // eyes
    const eyeGlow = this.isBoss || this.buffTimer > 0;
    if (eyeGlow) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = this.isBoss ? this.bossColors.eye : accent;
      ctx.globalAlpha = 0.18 + Math.sin(time * 7) * 0.05;
      ctx.beginPath();
      ctx.arc(hx + r * 0.12, -r * 0.23, r * 0.24, 0, TAU);
      ctx.arc(hx + r * 0.12, r * 0.23, r * 0.24, 0, TAU);
      ctx.fill();
      ctx.restore();
      ctx.globalAlpha = appear;
    }
    ctx.fillStyle = this.isBoss ? this.bossColors.eye : def.eye;
    ctx.beginPath();
    ctx.arc(hx + r * 0.17, -r * 0.21, Math.max(1.4, r * 0.075), 0, TAU);
    ctx.arc(hx + r * 0.17, r * 0.21, Math.max(1.4, r * 0.075), 0, TAU);
    ctx.fill();
    // jaw / mouth
    ctx.fillStyle = '#201113';
    ctx.beginPath();
    ctx.ellipse(hx + r * 0.26, 0, r * 0.16, r * 0.22, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(230,220,200,0.55)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(hx + r * 0.18, -r * 0.12);
    ctx.lineTo(hx + r * 0.3, -r * 0.12);
    ctx.moveTo(hx + r * 0.18, r * 0.12);
    ctx.lineTo(hx + r * 0.3, r * 0.12);
    ctx.stroke();

    // boss crown / horns
    if (this.isBoss) {
      ctx.fillStyle = this.bossColors.accent;
      ctx.globalAlpha = appear * 0.8;
      ctx.beginPath();
      ctx.moveTo(-r * 0.2, -r * 0.9);
      ctx.lineTo(-r * 0.5, -r * 1.32);
      ctx.lineTo(-r * 0.55, -r * 0.72);
      ctx.moveTo(-r * 0.15, r * 0.9);
      ctx.lineTo(-r * 0.42, r * 1.3);
      ctx.lineTo(-r * 0.5, r * 0.7);
      ctx.fill();
      ctx.globalAlpha = appear;
      // glowing core
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const core = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 0.8);
      core.addColorStop(0, this.enraged ? 'rgba(255,70,40,0.65)' : 'rgba(255,120,80,0.34)');
      core.addColorStop(1, 'rgba(255,60,40,0)');
      ctx.fillStyle = core;
      ctx.beginPath();
      ctx.arc(0, 0, r * 0.8, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // frozen tint
    if (this.frozen) {
      ctx.save();
      ctx.globalCompositeOperation = 'source-atop';
      ctx.fillStyle = 'rgba(140,210,255,0.22)';
      ctx.beginPath();
      ctx.arc(0, 0, r * 1.1, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // hit flash
    if (this.hitFlash > 0) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = `rgba(255,255,255,${Math.min(0.8, this.hitFlash * 7)})`;
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 1.05, r * 0.92, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // buff aura
    if (this.buffTimer > 0) {
      ctx.strokeStyle = `rgba(255,205,70,${0.25 + Math.sin(time * 6) * 0.12})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(0, 0, r + 3, 0, TAU);
      ctx.stroke();
    }

    ctx.restore();

    // health bar
    if (this.isBoss || (this.hp < this.maxHp && this.spawnT > 0.3)) {
      if (this.isBoss) {
        // main boss bar is DOM; small marker stays hidden
      } else {
        const w = Math.max(26, r * 2.1);
        const ratio = clamp(this.hp / this.maxHp, 0, 1);
        const y = this.y - r - 11;
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        ctx.fillRect(this.x - w / 2, y, w, 4);
        ctx.fillStyle = ratio > 0.5 ? '#9bc44a' : ratio > 0.25 ? '#ffb703' : '#e5383b';
        ctx.fillRect(this.x - w / 2, y, w * ratio, 4);
        ctx.strokeStyle = 'rgba(255,255,255,0.12)';
        ctx.lineWidth = 1;
        ctx.strokeRect(this.x - w / 2 + 0.5, y + 0.5, w - 1, 3);
      }
    }
  }
}

