import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/tmp/zo-shots', { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGE ERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__ZO__?.ready, null, { timeout: 15000 });
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/zo-shots/01-menu.png' });
console.log('menu snapshot', await page.evaluate(() => __ZO__.snapshot().mode));
await page.click('#btn-play');
await page.waitForTimeout(2500);
await page.screenshot({ path: '/tmp/zo-shots/02-play.png' });
console.log('playing', await page.evaluate(() => __ZO__.snapshot()));
console.log('errors', errors);
await browser.close();

