updateHUD() {
  const p = this.player;
  const hpPct = clamp(p.hp / p.maxHp, 0, 1) * 100;
  this.ui.hpFill.style.width = hpPct + '%';
  this.ui.hpText.textContent = String(Math.ceil(p.hp));
  this.ui.hpText.classList.toggle('low', hpPct < 30);
  this.ui.hpFill.classList.toggle('low', hpPct < 30);

  if (p.shield > 0) {
    this.ui.shieldWrap.classList.remove('hidden');
    this.ui.shieldFill.style.width = clamp(p.shield / p.shieldMax, 0, 1) * 100 + '%';
  } else {
    this.ui.shieldWrap.classList.add('hidden');
  }

  this.ui.waveNum.textContent = String(this.wave).padStart(2, '0');
  this.ui.coinNum.textContent = String(this.coins);
  this.ui.scoreNum.textContent = formatNumber(this.score);
  const remaining = this.spawnQueue.length + this.warnings.length + this.zombies.filter((z) => !z.dead).length;
  this.ui.enemiesNum.textContent = String(remaining);

  if (this.coins !== this.lastCoins) {
    if (this.coins > (this.lastCoins || 0)) {
      const chip = this.ui.coinNum.parentElement;
      chip.classList.remove('bump');
      void chip.offsetWidth;
      chip.classList.add('bump');
    }
    this.lastCoins = this.coins;
  }

  // weapons
  const cards = this.ui.weaponList.children;
  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];
    const wp = p.weapons[i];
    const def = wp.def;
    const active = i === p.weaponIndex;
    card.classList.toggle('active', active);
    card.classList.toggle('reloading', wp.reloading);
    card.classList.toggle('empty', wp.mag <= 0);
    const magEl = card.querySelector('[data-mag]');
    const resEl = card.querySelector('[data-res]');
    const relEl = card.querySelector('[data-reload]');
    const dryEl = card.querySelector('[data-dry]');
    if (magEl.textContent !== String(wp.mag)) magEl.textContent = String(wp.mag);
    const resText = wp.reserve === Infinity ? '/ ∞' : `/ ${wp.reserve}`;
    if (resEl.textContent !== resText) resEl.textContent = resText;
    if (wp.reloading) {
      const total = def.reload / p.stats.reloadSpeed;
      const progress = clamp(1 - wp.reloadTimer / total, 0, 1) * 100;
      relEl.style.width = progress + '%';
    } else {
      relEl.style.width = '0%';
    }
    const dry = wp.mag <= 0 && !wp.reloading;
    dryEl.style.display = dry ? 'block' : 'none';
    dryEl.textContent = wp.reserve > 0 ? 'RELOAD' : 'NO AMMO';
  }

  // boss
  if (this.boss && !this.boss.dead) {
    this.ui.bossBar.classList.remove('hidden');
    this.ui.bossName.textContent = this.boss.name;
    const pct = clamp(this.boss.hp / this.boss.maxHp, 0, 1) * 100;
    this.ui.bossFill.style.width = pct + '%';
    this.ui.bossHpText.textContent = `${Math.ceil(this.boss.hp)} / ${this.boss.maxHp}`;
  } else {
    this.ui.bossBar.classList.add('hidden');
  }
}

