220:     if (cur.reloading) { cur.reloading = false; cur.reloadTimer = 0; }
221:     this.weaponIndex = index;
222:     this.weapon.cooldown = Math.max(this.weapon.cooldown, 0.16);
223:     this.g.sound.swap();
224:     this.g.toast(this.weapon.def.name + ' READY', '');
225:   }
226: 
227:   cycleWeapon(delta) {
228:     const len = this.weapons.length;
229:     this.swapWeapon(((this.weaponIndex + delta) % len + len) % len);
230:   }
231: 
232:   startReload(silent = false) {
233:     const wp = this.weapon;
234:     if (wp.reloading || wp.mag >= wp.def.magSize) return;
235:     if (wp.reserve <= 0) {
236:       if (!silent) {
237:         this.g.sound.empty();
238:         this.g.toast('NO RESERVE AMMO — SCAVENGE CRATES', 'warn');
239:       }
240:       return;
241:     }
242:     wp.reloading = true;
243:     wp.reloadTimer = wp.def.reload / this.stats.reloadSpeed;
244:     if (!silent) this.g.sound.reload(0);
245:   }
246: 
247:   finishReload() {
248:     const wp = this.weapon;
249:     const need = wp.def.magSize - wp.mag;
250:     if (need <= 0) { wp.reloading = false; return; }
251:     if (wp.reserve === Infinity) {
252:       wp.mag = wp.def.magSize;
253:     } else {
254:       const take = Math.min(need, wp.reserve);
255:       wp.mag += take;
256:       wp.reserve -= take;
257:       wp.maxReserve = Math.round(wp.def.reserve * this.stats.reserveMul);
258:     }
259:     wp.reloading = false;
260:     this.g.sound.reload(1);
261:   }
262: 
263:   shoot() {
264:     const wp = this.weapon;
265:     const def = wp.def;
266:     if (wp.mag <= 0 || wp.reloading) return;
267:     wp.mag -= 1;
268:     const rapidMul = this.rapid > 0 ? 0.48 : 1;
269:     wp.cooldown = def.fireInterval / this.stats.fireRate * rapidMul;
270: 
271:     const movingSpread = Math.min(1.9, 1 + Math.hypot(this.vx, this.vy) / 420);
272:     const dmgMul = this.stats.damage * (this.damagePower > 0 ? 1.65 : 1);
273:     const muzzleX = this.x + Math.cos(this.aim) * (this.r + 12);
274:     const muzzleY = this.y + Math.sin(this.aim) * (this.r + 12);
275:     const pellets = def.pellets;
276: 
277:     for (let i = 0; i < pellets; i++) {
278:       let angle;
279:       if (pellets > 1) {
280:         const t = pellets === 1 ? 0 : i / (pellets - 1) - 0.5;
281:         angle = this.aim + t * def.spread * 2 + rand(-0.022, 0.022);
282:       } else {
283:         angle = this.aim + rand(-def.spread, def.spread) * movingSpread;
284:       }
285:       const crit = chance(this.stats.crit);
286:       const damage = def.damage * dmgMul * (crit ? 2 : 1);
287:       this.g.spawnBullet({
288:         x: muzzleX,
289:         y: muzzleY,
290:         angle,
291:         speed: def.speed * rand(0.97, 1.03),
292:         damage,
293:         crit,
294:         pierce: def.pierce + Math.floor(this.stats.pierce),
295:         knockback: def.knockback,
296:         color: def.tracer,
297:         weapon: def.id,
298:       });
299:     }
300: 
301:     // recoil, muzzle effects, sound
302:     this.vx -= Math.cos(this.aim) * def.recoil;
303:     this.vy -= Math.sin(this.aim) * def.recoil;
304:     this.muzzleFlash = 0.075;
305:     this.muzzleAngle = this.aim;
306:     this.g.shake(def.shake);
307:     this.g.crosshairKick = 1;
308:     const spreadParticles = def.id === 'shotgun' ? 9 : 4;
309:     for (let i = 0; i < spreadParticles; i++) {
310:       const a = this.aim + rand(-0.22, 0.22);
311:       const sp = rand(80, 320);
312:       this.g.spawnParticle({
313:         kind: 'spark', x: muzzleX, y: muzzleY, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
314:         life: rand(0.06, 0.18), maxLife: 0.18, size: rand(1, 2.4), color: def.id === 'shotgun' ? '#ffc98a' : '#ffe6a8', drag: 5,
315:       });
316:     }
317:     this.g.spawnParticle({
318:       kind: 'smoke', x: muzzleX, y: muzzleY, vx: Math.cos(this.aim) * 40, vy: Math.sin(this.aim) * 40,
319:       life: 0.35, maxLife: 0.35, size: rand(3, 6), color: 'rgba(200,190,170,0.16)', grow: 34,
320:     });
321:     // shell casing
322:     const casingA = this.aim + Math.PI / 2 + rand(-0.3, 0.3);
323:     this.g.spawnParticle({
324:       kind: 'casing', x: this.x + Math.cos(this.aim) * 10, y: this.y + Math.sin(this.aim) * 10,
325:       vx: Math.cos(casingA) * rand(60, 130), vy: Math.sin(casingA) * rand(60, 130) - 20,
326:       life: 1.6, maxLife: 1.6, size: 2.4, color: '#dcb45a', rot: rand(0, TAU), rotSpeed: rand(-12, 12), drag: 5,
327:     });
328:     this.g.sound.shoot(def.id);
329:     this.g.muzzleLight = { x: muzzleX, y: muzzleY, angle: this.aim, life: 0.075, max: 0.075, color: def.color };
330:     this.g.lastShotWeapon = def.id;
331:   }
