333:   takeDamage(amount, srcX = null, srcY = null, opts = {}) {
334:     if (this.hp <= 0 || this.invuln > 0 || this.dashTimer > 0 || this.g.mode !== 'playing') return false;
335:     let dmg = amount;
336:     if (this.shield > 0) {
337:       const absorbed = Math.min(this.shield, dmg);
338:       this.shield -= absorbed;
339:       dmg -= absorbed;
340:       this.shieldTimer = Math.max(this.shieldTimer, 1.5);
341:       this.g.sound.shieldHit();
342:       this.g.ring(this.x, this.y, this.r + 12, 'rgba(90,215,255,0.65)', 0.4, 90);
343:       this.g.shake(4);
344:       if (dmg <= 0) {
345:         this.invuln = 0.35;
346:         return true;
347:       }
348:     }
349:     dmg *= (1 - this.stats.armor);
350:     this.hp = Math.max(0, this.hp - dmg);
351:     this.invuln = 0.68;
352:     this.hurtTimer = 0.35;
353:     this.g.damageFlash = Math.min(1, this.g.damageFlash + 0.75);
354:     this.g.shake(8 + dmg * 0.22);
355:     this.g.sound.hurt();
356:     this.g.floatText(this.x, this.y - 24, '-' + Math.round(dmg), '#ff5c5f', 17);
357:     this.g.burstBlood(this.x, this.y, 7, '#a51e25', 160);
358:     this.g.hitDirection = srcX !== null ? Math.atan2(this.y - srcY, this.x - srcX) : rand(0, TAU);
359:     if (srcX !== null) {
360:       const n = norm(this.x - srcX, this.y - srcY);
361:       this.vx += n.x * 130;
362:       this.vy += n.y * 130;
363:     }
364:     if (this.hp <= 0) this.g.gameOver();
365:     return true;
366:   }
