368:   heal(amount) {
369:     const before = this.hp;
370:     this.hp = Math.min(this.maxHp, this.hp + amount);
371:     return this.hp - before;
372:   }
373: 
374:   addShield(amount, time = 12) {
375:     this.shieldMax = Math.max(this.shieldMax, amount);
376:     this.shield = Math.min(this.shieldMax, this.shield + amount);
377:     this.shieldTimer = Math.max(this.shieldTimer, time);
378:   }
379: 
380:   addAmmo(frac = 0.35) {
381:     let added = 0;
382:     for (const w of this.weapons) {
383:       if (w.reserve === Infinity) continue;
384:       w.maxReserve = Math.round(w.def.reserve * this.stats.reserveMul);
385:       const before = w.reserve;
386:       w.reserve = Math.min(w.maxReserve, w.reserve + Math.ceil(w.maxReserve * frac));
387:       added += w.reserve - before;
388:     }
389:     return added;
390:   }
391: 
392:   refillReserves() {
393:     for (const w of this.weapons) {
394:       if (w.reserve === Infinity) continue;
395:       w.maxReserve = Math.round(w.def.reserve * this.stats.reserveMul);
396:       w.reserve = w.maxReserve;
397:     }
398:   }
