653:     this.attackCd = Math.max(0, this.attackCd - dt);
654:     this.contactCd = Math.max(0, this.contactCd - dt);
655:     this.lungeCd = Math.max(0, this.lungeCd - dt);
656:     this.lungeTimer = Math.max(0, this.lungeTimer - dt);
657:     this.fireCd = Math.max(0, this.fireCd - dt);
658:     this.pulseCd = Math.max(0, this.pulseCd - dt);
659:     this.attackAnim = Math.max(0, this.attackAnim - dt);
660:     this.buffTimer = Math.max(0, this.buffTimer - dt);
661:     this.slowTimer = Math.max(0, this.slowTimer - dt);
662:     this.growlTimer -= dt;
663:     if (this.growlTimer <= 0) {
664:       this.growlTimer = rand(5, 11);
665:       if (this.g.camVisible(this.x, this.y, 300)) this.g.sound.growl(this.isBoss ? 0.5 : 1);
666:     }
667: 
668:     if (this.spawnT < 0.3 || this.dead) return;
669: 
670:     const p = this.g.player;
671:     const dx = p.x - this.x;
672:     const dy = p.y - this.y;
673:     const d = Math.hypot(dx, dy) || 0.001;
674:     const nx = dx / d;
675:     const ny = dy / d;
