701:       } else if (d > pref + 70) {
702:         vx = nx * speed;
703:         vy = ny * speed;
704:       } else {
705:         const strafe = Math.sin(this.g.time * 0.9 + this.anim) * speed * 0.55;
706:         vx = -ny * strafe;
707:         vy = nx * strafe;
