709:       if (this.fireCd <= 0 && d < 560 && this.windup <= 0) {
710:         this.windup = 0.42;
711:         this.windupKind = 'spit';
712:         this.fireCd = this.def.attackCd * rand(0.85, 1.2);
713:       }
714:       animSpeed = 0.7;
715:     } else if (this.type === 'brute') {
716:       vx = nx * speed;
717:       vy = ny * speed;
718:       animSpeed = 0.6;
719:       if (d < 130 && this.attackCd <= 0 && this.windup <= 0) {
720:         this.windup = 0.62;
721:         this.windupKind = 'slam';
722:         this.attackCd = this.def.attackCd + 1.1;
723:         this.angle = Math.atan2(dy, dx);
724:         this.g.ring(this.x, this.y, 100, 'rgba(229,56,59,0.34)', 0.62, 0);
725:         this.g.sound.growl(0.6);
726:       }
727:       if (this.windup > 0) { vx = 0; vy = 0; }
728:     } else if (this.type === 'runner') {
729:       vx = nx * speed;
730:       vy = ny * speed;
731:       animSpeed = 1.6;
732:       if (this.lungeCd <= 0 && d > 70 && d < 250) {
733:         this.lungeCd = rand(2.8, 4.2);
734:         this.lungeTimer = 0.33;
735:         this.angle = Math.atan2(dy, dx);
736:         this.g.burstSparks(this.x, this.y, 4, '#d8cba8', 70, 0.25);
737:       }
738:       if (this.lungeTimer > 0) {
739:         vx *= 2.8;
740:         vy *= 2.8;
741:         this.g.spawnParticle({
742:           kind: 'smoke', x: this.x, y: this.y + 3, vx: -vx * 0.05, vy: -vy * 0.05,
743:           life: 0.28, maxLife: 0.28, size: 3, color: 'rgba(170,160,140,0.14)', grow: 7,
744:         });
745:       }
746:     } else if (this.type === 'screamer') {
747:       vx = nx * speed * 0.85;
748:       vy = ny * speed * 0.85;
749:       if (this.pulseCd <= 0) {
750:         this.pulseCd = 4.2;
751:         this.g.screamerPulse(this);
752:       }
753:       animSpeed = 1.1;
754:     } else {
755:       vx = nx * speed;
756:       vy = ny * speed;
757:       animSpeed = 1;
758:       if (this.type === 'walker' && this.g.time % 7 < dt) {
759:         vx *= 0.4;
760:         vy *= 0.4;
761:       }
762:     }
763: 
764:     // windup handling
765:     if (this.windup > 0) {
766:       this.windup -= dt;
767:       vx = 0;
768:       vy = 0;
769:       if (this.windupKind === 'slam') {
770:         this.g.spawnParticle({
771:           kind: 'smoke', x: this.x + rand(-20, 20), y: this.y + 8, vx: rand(-10, 10), vy: rand(-4, 2),
772:           life: 0.3, maxLife: 0.3, size: rand(4, 8), color: 'rgba(120,110,90,0.2)', grow: 16,
773:         });
774:       }
775:       if (this.windup <= 0) this.resolveWindup(d);
776:     }
777: 
778:     // separation from other zombies
779:     let sx = 0;
780:     let sy = 0;
781:     const zombies = this.g.zombies;
782:     for (let i = 0; i < zombies.length; i++) {
783:       const o = zombies[i];
784:       if (o === this || o.dead) continue;
785:       const ox = this.x - o.x;
786:       const oy = this.y - o.y;
787:       const min = (this.r + o.r) * 0.82;
788:       const od2 = ox * ox + oy * oy;
789:       if (od2 > 0.001 && od2 < min * min) {
790:         const od = Math.sqrt(od2);
791:         const force = (min - od) / min;
792:         sx += (ox / od) * force;
793:         sy += (oy / od) * force;
794:       }
795:     }
796:     vx += sx * speed * 0.9;
797:     vy += sy * speed * 0.9;
798: 
799:     // avoid stacking directly on the player
800:     if (d < this.r + p.r * 0.65) {
801:       vx -= nx * speed * 0.8;
802:       vy -= ny * speed * 0.8;
803:     }
804: 
805:     const accel = 1 - Math.exp(-(this.isBoss ? 4 : 9) * dt);
806:     this.vx = lerp(this.vx, vx, accel);
807:     this.vy = lerp(this.vy, vy, accel);
808:     this.x += this.vx * dt;
809:     this.y += this.vy * dt;
810:     this.anim += dt * animSpeed * (1 + Math.hypot(this.vx, this.vy) / 300);
811: 
812:     // melee
813:     if (d < this.r + p.r + 5 && this.attackCd <= 0 && this.windup <= 0) {
814:       if (this.type === 'brute') {
815:         // handled by windup, do nothing
816:       } else {
817:         this.attackCd = this.def.attackCd * rand(0.9, 1.15);
818:         this.attackAnim = 0.22;
819:         p.takeDamage(this.damage * (this.buffTimer > 0 ? 1.2 : 1), this.x, this.y);
820:         this.g.burstBlood(p.x, p.y, 2, '#7a1218', 70);
821:       }
822:     }
823: 
824:     const w = this.g.world;
825:     this.x = clamp(this.x, 40, w.w - 40);
826:     this.y = clamp(this.y, 40, w.h - 40);
827:   }
