829:   resolveWindup(d) {
830:     const p = this.g.player;
831:     if (this.windupKind === 'slam') {
832:       this.g.sound.slam();
833:       this.g.shake(13);
834:       this.g.ring(this.x, this.y, 100, 'rgba(255,120,90,0.65)', 0.55, 420);
835:       this.g.dustBurst(this.x, this.y, 22, '#6b5d4a');
836:       if (d < 122) p.takeDamage(this.damage * 1.25, this.x, this.y);
837:     } else if (this.windupKind === 'spit') {
838:       const angle = Math.atan2(p.y - this.y, p.x - this.x) + rand(-0.05, 0.05);
839:       this.g.spawnAcid(this.x + Math.cos(angle) * this.r, this.y + Math.sin(angle) * this.r, angle, this.damage, 420);
840:       this.g.sound.spit();
841:       this.attackAnim = 0.3;
842:     }
843:     this.windupKind = null;
844:   }
