846:   updateBoss(dt, d, nx, ny, speed) {
847:     const p = this.g.player;
848:     if (!this.enraged && this.hp < this.maxHp * 0.35) {
849:       this.enraged = true;
850:       this.speed *= 1.22;
851:       this.g.toast(`${this.name} IS ENRAGED`, 'danger');
852:       this.g.sound.boss();
853:       this.g.shake(10);
854:       this.g.ring(this.x, this.y, this.r + 40, 'rgba(255,60,60,0.8)', 0.8, 380);
855:     }
856: 
857:     const face = Math.atan2(p.y - this.y, p.x - this.x);
858:     if (this.state === 'chase') {
859:       if (this.windup <= 0) this.angle = angleLerp(this.angle, face, 1 - Math.exp(-5 * dt));
860:       this.vx = lerp(this.vx, nx * speed, 1 - Math.exp(-4 * dt));
861:       this.vy = lerp(this.vy, ny * speed, 1 - Math.exp(-4 * dt));
862:       this.x += this.vx * dt;
863:       this.y += this.vy * dt;
864:       this.anim += dt * (1 + Math.hypot(this.vx, this.vy) / 300);
865:       this.bossAtkCd -= dt;
866:       if (d < this.r + p.r + 6 && this.contactCd <= 0) {
867:         this.contactCd = 0.85;
868:         p.takeDamage(this.damage, this.x, this.y);
869:         this.attackAnim = 0.3;
870:       }
871:       if (this.bossAtkCd <= 0) this.chooseBossAttack(d);
872:     } else if (this.state === 'chargeWind') {
873:       this.stateTimer -= dt;
874:       this.angle = angleLerp(this.angle, face, 1 - Math.exp(-9 * dt));
875:       this.chargeAngle = this.angle;
876:       this.vx *= 0.85;
877:       this.vy *= 0.85;
878:       this.g.spawnParticle({
879:         kind: 'ember', x: this.x + rand(-this.r, this.r), y: this.y + rand(-this.r, this.r),
880:         vx: rand(-20, 20), vy: rand(-30, 0), life: 0.4, maxLife: 0.4, size: rand(2, 4), color: 'rgba(255,120,90,0.7)',
881:       });
882:       if (this.stateTimer <= 0) {
883:         this.state = 'charge';
884:         this.stateTimer = 0.55;
885:         this.chargeHit = false;
886:         this.vx = Math.cos(this.chargeAngle) * 760;
887:         this.vy = Math.sin(this.chargeAngle) * 760;
888:         this.g.shake(6);
889:         this.g.sound.growl(0.4);
890:       }
891:     } else if (this.state === 'charge') {
892:       this.stateTimer -= dt;
893:       this.x += this.vx * dt;
894:       this.y += this.vy * dt;
895:       this.anim += dt * 6;
896:       if (chance(dt * 50)) {
897:         this.g.dustBurst(this.x - Math.cos(this.chargeAngle) * 20, this.y - Math.sin(this.chargeAngle) * 20, 3, '#675a48');
898:       }
899:       if (!this.chargeHit && d < this.r + p.r + 12) {
900:         this.chargeHit = true;
901:         p.takeDamage(this.damage * 1.35, this.x, this.y);
902:         this.g.shake(14);
903:       }
904:       if (this.stateTimer <= 0) {
905:         this.state = 'recover';
906:         this.stateTimer = this.enraged ? 0.55 : 0.9;
907:         this.bossAtkCd = this.enraged ? 1.6 : 2.3;
908:       }
909:     } else if (this.state === 'slamWind') {
910:       this.stateTimer -= dt;
911:       this.vx *= 0.8;
912:       this.vy *= 0.8;
913:       if (chance(dt * 25)) this.g.dustBurst(this.x, this.y + 10, 2, '#5b5044');
914:       if (this.stateTimer <= 0) {
915:         this.state = 'recover';
916:         this.stateTimer = 0.95;
917:         this.bossAtkCd = this.enraged ? 1.7 : 2.5;
918:         this.g.sound.slam();
919:         this.g.shake(20);
920:         this.g.spawnShockwave(this.x, this.y, 300, this.damage * 1.5, '#ff6b5c');
921:         this.g.dustBurst(this.x, this.y, 30, '#6b5d4a');
922:       }
923:     } else if (this.state === 'summon') {
924:       this.stateTimer -= dt;
925:       if (this.stateTimer <= 0) {
926:         const count = this.enraged ? 6 : 4;
927:         for (let i = 0; i < count; i++) {
928:           const a = (i / count) * TAU + rand(-0.2, 0.2);
929:           const r = this.r + rand(30, 70);
930:           const types = this.g.availableZombieTypes().filter((t) => t !== 'brute');
931:           const t = types.length ? types[randInt(0, types.length - 1)] : 'walker';
932:           this.g.spawnZombie(t, this.x + Math.cos(a) * r, this.y + Math.sin(a) * r, { noWarning: true });
933:           this.g.burstBlood(this.x + Math.cos(a) * r, this.y + Math.sin(a) * r, 4, '#3a0d0f', 100);
934:         }
935:         this.g.toast(`${this.name} CALLS THE HORDE`, 'danger');
936:         this.g.sound.boss();
937:         this.state = 'recover';
938:         this.stateTimer = 0.9;
939:         this.bossAtkCd = this.enraged ? 1.6 : 2.4;
940:       }
941:     } else if (this.state === 'volley') {
942:       this.stateTimer -= dt;
943:       if (this.stateTimer <= 0) {
944:         const base = Math.atan2(p.y - this.y, p.x - this.x);
945:         const count = this.enraged ? 9 : 6;
946:         for (let i = 0; i < count; i++) {
947:           const a = base + (i - (count - 1) / 2) * 0.16;
948:           this.g.spawnAcid(this.x + Math.cos(a) * this.r, this.y + Math.sin(a) * this.r, a, this.damage * 0.7, 470);
949:         }
950:         this.g.sound.spit();
951:         this.state = 'recover';
952:         this.stateTimer = 0.75;
953:         this.bossAtkCd = this.enraged ? 1.5 : 2.2;
954:       }
955:     } else if (this.state === 'recover') {
956:       this.stateTimer -= dt;
957:       this.vx *= 0.86;
958:       this.vy *= 0.86;
959:       if (this.stateTimer <= 0) this.state = 'chase';
960:     }
961: 
962:     const w = this.g.world;
963:     this.x = clamp(this.x, 54, w.w - 54);
964:     this.y = clamp(this.y, 54, w.h - 54);
965:   }
