967:   chooseBossAttack(d) {
968:     const roll = Math.random();
969:     if (d < 210) {
970:       if (roll < 0.45) this.beginSlam();
971:       else if (roll < 0.7) this.beginSummon();
972:       else if (roll < 0.88) this.beginVolley();
973:       else this.beginCharge();
974:     } else {
975:       if (roll < 0.44) this.beginCharge();
976:       else if (roll < 0.66) this.beginSummon();
977:       else if (roll < 0.9) this.beginVolley();
978:       else this.beginSlam();
979:     }
980:   }
