1016:   drawTelegraph(ctx) {
1017:     if (!this.isBoss) return;
1018:     const pulse = 0.5 + Math.sin(this.g.time * 12) * 0.2;
1019:     if (this.state === 'chargeWind') {
1020:       ctx.save();
1021:       ctx.translate(this.x, this.y);
1022:       ctx.rotate(this.chargeAngle);
1023:       const grad = ctx.createLinearGradient(0, 0, 780, 0);
1024:       grad.addColorStop(0, `rgba(255,55,55,${0.3 * pulse + 0.12})`);
1025:       grad.addColorStop(0.8, 'rgba(255,55,55,0.1)');
1026:       grad.addColorStop(1, 'rgba(255,55,55,0)');
1027:       ctx.fillStyle = grad;
1028:       ctx.fillRect(0, -this.r * 0.6, 780, this.r * 1.2);
1029:       ctx.strokeStyle = `rgba(255,90,90,${pulse})`;
1030:       ctx.lineWidth = 2;
1031:       ctx.setLineDash([12, 10]);
1032:       ctx.beginPath();
1033:       ctx.moveTo(0, 0);
1034:       ctx.lineTo(780, 0);
1035:       ctx.stroke();
1036:       ctx.restore();
1037:     } else if (this.state === 'slamWind') {
1038:       ctx.save();
1039:       ctx.strokeStyle = `rgba(255,80,60,${0.35 + pulse * 0.4})`;
1040:       ctx.fillStyle = `rgba(255,60,40,${0.05 + pulse * 0.05})`;
1041:       ctx.lineWidth = 3;
1042:       ctx.setLineDash([14, 9]);
1043:       ctx.beginPath();
1044:       ctx.arc(this.x, this.y, 300, 0, TAU);
1045:       ctx.fill();
1046:       ctx.stroke();
1047:       ctx.setLineDash([]);
1048:       ctx.restore();
1049:     }
1050:   }
