1052:   render(ctx, time) {
1053:     if (this.spawnT < 0.3) {
1054:       // rise-from-ground spawn effect drawn by the warning; keep entity mostly hidden
1055:     }
1056:     const appear = clamp(this.spawnT / 0.3, 0, 1);
1057:     const scale = this.isBoss ? easeOutCubic(appear) : lerp(0.55, 1, easeOutCubic(appear));
1058:     const def = this.def;
1059:     const bodyCol = this.isBoss ? this.bossColors.body : def.body;
1060:     const darkCol = this.isBoss ? this.bossColors.dark : def.bodyDark;
1061:     const skinCol = this.isBoss ? this.bossColors.skin : def.skin;
1062:     const accent = this.isBoss ? this.bossColors.accent : def.accent;
1063: 
1064:     // shadow
1065:     ctx.save();
1066:     ctx.translate(this.x, this.y);
1067:     ctx.globalAlpha = appear;
1068:     ctx.fillStyle = 'rgba(0,0,0,0.4)';
1069:     ctx.beginPath();
1070:     ctx.ellipse(0, this.r * 0.5, this.r * 1.15, this.r * 0.62, 0, 0, TAU);
1071:     ctx.fill();
1072:     ctx.restore();
1073: 
1074:     ctx.save();
1075:     ctx.translate(this.x, this.y);
1076:     ctx.scale(scale, scale);
1077:     ctx.rotate(this.angle);
1078:     ctx.globalAlpha = appear;
1079:     const r = this.r;
1080:     const wobble = Math.sin(this.anim * 6) * 0.12;
1081: 
1082:     // legs
1083:     ctx.strokeStyle = darkCol;
1084:     ctx.lineWidth = Math.max(4, r * 0.24);
1085:     ctx.lineCap = 'round';
1086:     ctx.beginPath();
1087:     ctx.moveTo(-r * 0.3, -r * 0.34);
1088:     ctx.lineTo(-r * 0.72, -r * 0.6 + Math.sin(this.anim * 7) * r * 0.16);
1089:     ctx.moveTo(-r * 0.3, r * 0.34);
1090:     ctx.lineTo(-r * 0.72, r * 0.6 - Math.sin(this.anim * 7) * r * 0.16);
1091:     ctx.stroke();
1092: 
1093:     // arms reaching
1094:     const reach = this.attackAnim > 0 ? 1.22 : 1;
1095:     ctx.strokeStyle = skinCol;
1096:     ctx.lineWidth = Math.max(3.5, r * 0.2);
1097:     ctx.beginPath();
1098:     ctx.moveTo(r * 0.1, -r * 0.55);
1099:     ctx.lineTo(r * 0.92 * reach, -r * 0.68 - wobble * r);
1100:     ctx.lineTo(r * 1.18 * reach, -r * 0.36);
1101:     ctx.moveTo(r * 0.1, r * 0.55);
1102:     ctx.lineTo(r * 0.92 * reach, r * 0.68 - wobble * r);
1103:     ctx.lineTo(r * 1.18 * reach, r * 0.36);
1104:     ctx.stroke();
1105:     // hands
1106:     ctx.fillStyle = skinCol;
1107:     ctx.beginPath();
1108:     ctx.arc(r * 1.2 * reach, -r * 0.34, r * 0.16, 0, TAU);
1109:     ctx.arc(r * 1.2 * reach, r * 0.34, r * 0.16, 0, TAU);
1110:     ctx.fill();
1111: 
1112:     // body
1113:     ctx.fillStyle = bodyCol;
1114:     ctx.beginPath();
1115:     if (this.type === 'runner') {
1116:       ctx.ellipse(0, 0, r * 0.78, r * 0.58, 0, 0, TAU);
1117:     } else if (this.type === 'brute' || this.isBoss) {
1118:       ctx.ellipse(0, 0, r * 0.98, r * 0.88, 0, 0, TAU);
1119:     } else {
1120:       ctx.ellipse(0, 0, r * 0.84, r * 0.72, 0, 0, TAU);
1121:     }
1122:     ctx.fill();
1123:     ctx.strokeStyle = darkCol;
1124:     ctx.lineWidth = 2;
1125:     ctx.stroke();
1126: 
1127:     // torn shirt / ribs
1128:     ctx.strokeStyle = darkCol;
1129:     ctx.lineWidth = Math.max(1, r * 0.07);
1130:     ctx.globalAlpha = appear * 0.7;
1131:     ctx.beginPath();
1132:     ctx.arc(0, 0, r * 0.52, -0.8, 0.3);
1133:     ctx.stroke();
1134:     ctx.beginPath();
1135:     ctx.moveTo(-r * 0.25, -r * 0.4);
1136:     ctx.lineTo(-r * 0.4, -r * 0.15);
1137:     ctx.stroke();
1138:     ctx.globalAlpha = appear;
1139: 
1140:     // shoulders spikes for brute/boss
1141:     if (this.type === 'brute' || this.isBoss) {
1142:       ctx.fillStyle = accent;
1143:       ctx.globalAlpha = appear * 0.5;
1144:       for (let i = 0; i < 4; i++) {
1145:         const a = -0.9 + i * 0.6;
1146:         ctx.beginPath();
1147:         ctx.moveTo(Math.cos(a) * r * 0.72, Math.sin(a) * r * 0.72);
1148:         ctx.lineTo(Math.cos(a) * r * 1.12, Math.sin(a) * r * 1.12);
1149:         ctx.lineTo(Math.cos(a + 0.18) * r * 0.7, Math.sin(a + 0.18) * r * 0.7);
1150:         ctx.fill();
1151:       }
1152:       ctx.globalAlpha = appear;
1153:     }
1154: 
1155:     // spitter sac
1156:     if (this.type === 'spitter') {
1157:       ctx.fillStyle = 'rgba(157,255,77,0.5)';
1158:       ctx.beginPath();
1159:       ctx.ellipse(-r * 0.1, 0, r * 0.38, r * 0.5, 0, 0, TAU);
1160:       ctx.fill();
1161:       ctx.strokeStyle = 'rgba(190,255,120,0.55)';
1162:       ctx.lineWidth = 1;
1163:       ctx.stroke();
1164:     }
1165: 
1166:     // screamer ribs / open mouth
1167:     if (this.type === 'screamer') {
1168:       ctx.fillStyle = accent;
1169:       ctx.globalAlpha = appear * 0.55;
1170:       ctx.beginPath();
1171:       ctx.arc(0, 0, r * 0.3 + Math.sin(time * 8) * r * 0.04, 0, TAU);
1172:       ctx.fill();
1173:       ctx.globalAlpha = appear;
1174:     }
1175: 
1176:     // head
1177:     const hx = r * 0.62;
1178:     ctx.fillStyle = skinCol;
1179:     ctx.beginPath();
1180:     ctx.arc(hx, 0, r * 0.48, 0, TAU);
1181:     ctx.fill();
1182:     ctx.strokeStyle = darkCol;
1183:     ctx.lineWidth = 1.5;
1184:     ctx.stroke();
1185:     // hair patch at back
1186:     ctx.fillStyle = darkCol;
1187:     ctx.beginPath();
1188:     ctx.arc(hx - r * 0.16, 0, r * 0.38, Math.PI * 0.52, Math.PI * 1.48);
1189:     ctx.fill();
1190:     // eyes
1191:     const eyeGlow = this.isBoss || this.buffTimer > 0;
1192:     if (eyeGlow) {
1193:       ctx.save();
1194:       ctx.globalCompositeOperation = 'lighter';
1195:       ctx.fillStyle = this.isBoss ? this.bossColors.eye : accent;
1196:       ctx.globalAlpha = 0.18 + Math.sin(time * 7) * 0.05;
1197:       ctx.beginPath();
1198:       ctx.arc(hx + r * 0.12, -r * 0.23, r * 0.24, 0, TAU);
1199:       ctx.arc(hx + r * 0.12, r * 0.23, r * 0.24, 0, TAU);
1200:       ctx.fill();
1201:       ctx.restore();
1202:       ctx.globalAlpha = appear;
1203:     }
1204:     ctx.fillStyle = this.isBoss ? this.bossColors.eye : def.eye;
