input.content:
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/tmp/zo-shots', { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => { errors.push('pageerror: ' + e.message); console.log('PAGE ERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push('console: ' + m.text()); console.log('CONSOLE ERROR:', m.text()); } });

let passed = 0;
let failed = 0;
const check = (name, condition, extra = '') => {
  if (condition) {
    passed++;
    console.log('  PASS', name);
  } else {
    failed++;
    console.log('  FAIL', name, extra);
  }
};
const section = (name) => console.log('\n## ' + name);

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__ZO__?.ready, null, { timeout: 15000 });

section('Menu');
await page.waitForTimeout(300);
check('menu is active', await page.evaluate(() => __ZO__.snapshot().mode === 'menu'));
check('menu overlay visible', await page.locator('#menu').evaluate((el) => el.classList.contains('active')));
check('HUD hidden in menu', await page.locator('#hud').evaluate((el) => el.classList.contains('hidden')));
await page.screenshot({ path: '/tmp/zo-shots/10-menu-final.png' });

section('Start and movement');
await page.click('#btn-play');
await page.waitForTimeout(250);
check('playing after deploy', await page.evaluate(() => __ZO__.snapshot().mode === 'playing'));
check('HUD visible', await page.locator('#hud').evaluate((el) => !el.classList.contains('hidden')));
check('wave 1', await page.evaluate(() => __ZO__.snapshot().wave === 1));

const move = await page.evaluate(() => {
  const g = __ZO__.game;
  g.spawnQueue = [];
  g.warnings = [];
  g.zombies = [];
  g.player.x = 1400;
  g.player.y = 1400;
  g.player.vx = 0;
  g.player.vy = 0;
  g.camera.x = 1400;
  g.camera.y = 1400;
  g.waveEndTimer = 999;
  const before = { x: g.player.x, y: g.player.y };
  g.input.keys.add('KeyD');
  __ZO__.step(0.6);
  g.input.keys.delete('KeyD');
  const after = { x: g.player.x, y: g.player.y };
  return { before, after, vx: g.player.vx };
});
check('keyboard moves player right', move.after.x > move.before.x + 40, JSON.stringify(move));
check('movement produces velocity', Math.abs(move.vx) > 20, JSON.stringify(move));

section('Aiming and hit feedback');
const aim = await page.evaluate(() => {
  const g = __ZO__.game;
  const p = g.player;
  g.input.mouse.x = g.w / 2;
  g.input.mouse.y = g.h / 2 + 220;
  const before = p.aim;
  __ZO__.step(0.35);
  return { before, after: p.aim, screen: { w: g.w, h: g.h } };
});
check('mouse aim rotates toward pointer', Math.abs(aim.after - Math.PI / 2) < 0.25, JSON.stringify(aim));
check('mouse-screen is down', await page.evaluate(() => __ZO__.game.player.aim > 0.9));

section('Pistol firing, damage, kills, coins');
const pistol = await page.evaluate(() => {
  const g = __ZO__.game;
  const p = g.player;
  g.zombies = [];
  g.bullets = [];
  g.spawnQueue = [];
  g.warnings = [];
  p.x = 1400; p.y = 1400; p.vx = 0; p.vy = 0;
  g.camera.x = 1400; g.camera.y = 1400;
  p.weaponIndex = 0;
  p.weapons[0].mag = 12;
  p.weapons[0].reloading = false;
  const z = __ZO__.spawnAt('walker', 1600, 1400);
  z.spawnT = 0.3;
  const magBefore = p.weapons[0].mag;
  const shots = [];
  for (let i = 0; i < 5; i++) {
    __ZO__.aimAt(1, 0);
    __ZO__.fire();
    __ZO__.step(0.12);
    shots.push({ mag: p.weapons[0].mag, hp: z.hp, dead: z.dead });
    if (z.dead) break;
  }
  const coinsBefore = g.coins;
  // walk over dropped coins / pickups
  for (const it of g.pickups) { it.x = p.x; it.y = p.y; }
  __ZO__.step(0.25);
  return {
    magBefore, shots, kills: g.kills, score: g.score,
    coinsBefore, coins: g.coins, pickups: g.pickups.length,
    bullets: g.bullets.length,
  };
});
check('pistol magazine decrements', pistol.shots[0].mag === 11, JSON.stringify(pistol));
check('bullet damages zombie', pistol.shots[0].hp < 74, JSON.stringify(pistol));
check('pistol kills a walker', pistol.kills === 1, JSON.stringify(pistol));
check('kill awards score', pistol.score > 0, JSON.stringify(pistol));
check('kill drops coins or loot', pistol.pickups >= 0, JSON.stringify(pistol));

section('Reload');
const reload = await page.evaluate(() => {
  const g = __ZO__.game;
  const p = g.player;
  p.weaponIndex = 0;
  const wp = p.weapons[0];
  wp.mag = 2; wp.reserve = Infinity; wp.reloading = false; wp.cooldown = 0;
  p.startReload();
  const started = { reloading: wp.reloading, timer: wp.reloadTimer, mag: wp.mag };
  __ZO__.step(1.2);
  return { started, after: { reloading: wp.reloading, mag: wp.mag } };
});
check('reload starts', reload.started.reloading === true, JSON.stringify(reload));
check('reload completes and fills magazine', !reload.after.reloading && reload.after.mag === 12, JSON.stringify(reload));

section('Shotgun');
const shotgun = await page.evaluate(() => {
  const g = __ZO__.game;
  const p = g.player;
  g.zombies = []; g.bullets = []; g.pickups = [];
  p.x = 1400; p.y = 1400; p.vx = 0; p.vy = 0;
  p.weaponIndex = 1;
  p.weapons[1].mag = 6;
  p.weapons[1].reloading = false;
  p.weapons[1].cooldown = 0;
  __ZO__.aimAt(1, 0);
  const z = __ZO__.spawnAt('walker', 1510, 1400);
  z.spawnT = 0.3;
  __ZO__.fire();
  const fired = { bullets: g.bullets.length, mag: p.weapons[1].mag };
  __ZO__.step(0.18);
  return { fired, hp: z.hp, dead: z.dead, mag: p.weapons[1].mag };
});
check('shotgun fires eight pellets', shotgun.fired.bullets === 8, JSON.stringify(shotgun));
check('shotgun consumes one shell', shotgun.fired.mag === 5, JSON.stringify(shotgun));
check('shotgun close-range damage is lethal', shotgun.dead || shotgun.hp < 20, JSON.stringify(shotgun));

section('SMG automatic fire and auto-reload');
const smg = await page.evaluate(() => {
  const g = __ZO__.game;
  const p = g.player;
  g.zombies = []; g.bullets = []; g.pickups = []; g.spawnQueue = []; g.warnings = [];
  p.x = 1400; p.y = 1400; p.vx = 0; p.vy = 0;
  p.weaponIndex = 2;
  const wp = p.weapons[2];
  wp.mag = 30; wp.reserve = 210; wp.reloading = false; wp.cooldown = 0;
  g.camera.x = 1400; g.camera.y = 1400;
  g.input.mouse.x = g.w / 2 + 300;
  g.input.mouse.y = g.h / 2;
  const target = __ZO__.spawnAt('brute', 1640, 1400);
  target.spawnT = 0.3;
  target.maxHp = 10000;
  target.hp = 10000;
  g.input.mouse.down = true;
  __ZO__.step(0.6);
  g.input.mouse.down = false;
  const afterBurst = { mag: wp.mag, bullets: g.bullets.length, reloading: wp.reloading };
  // empty it and let auto-reload happen while trigger held
  wp.mag = 1; wp.reserve = 210; wp.cooldown = 0;
  g.input.mouse.down = true;
  __ZO__.step(2.4);
  g.input.mouse.down = false;
  return { afterBurst, afterReload: { mag: wp.mag, reserve: wp.reserve, reloading: wp.reloading } };
});
check('SMG fires automatically', smg.afterBurst.mag < 30, JSON.stringify(smg));
check('SMG creates many bullets', smg.afterBurst.bullets > 2, JSON.stringify(smg));
check('SMG auto-reloads when empty', smg.afterReload.mag > 0 && smg.afterReload.reserve < 210, JSON.stringify(smg));

section('Player damage, shield and health pickup');
const survival = await page.evaluate(() => {
  const g = __ZO__.game;
  const p = g.player;
  g.zombies = []; g.bullets = []; g.pickups = [];
  p.x = 1400; p.y = 1400;
  p.hp = 100; p.maxHp = 100; p.shield = 0; p.invuln = 0;
  p.takeDamage(20, p.x + 20, p.y);
  const hurt = { hp: p.hp, invuln: p.invuln, flash: g.damageFlash, text: g.texts.length };
  p.invuln = 0;
  g.applyPowerup({ id: 'shield', name: 'AEGIS SHIELD', icon: '⛨', color: '#4cc9f0', duration: 12 });
  const shieldBefore = p.shield;
  p.takeDamage(25, p.x + 20, p.y);
  const shielded = { hp: p.hp, shield: p.shield, before: shieldBefore };
  p.invuln = 0;
  p.hp = 40;
