import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
await page.goto('http://localhost:3002/');
await page.waitForFunction(() => window.__ZO__?.ready);
await page.click('#btn-play');
await page.waitForTimeout(200);
const res = await page.evaluate(() => {
  const g = __ZO__.game;
  const out = [];
  const snap = (label) => out.push({ label, mode: g.mode, time: g.time, wave: g.wave, waveEndTimer: g.waveEndTimer, spawnQueue: g.spawnQueue.length, warnings: g.warnings.length, zombies: g.zombies.length, reloading: g.player.weapons[0].reloading, reloadTimer: g.player.weapons[0].reloadTimer, mag: g.player.weapons[0].mag, hp: g.player.hp });
  snap('start');
  g.spawnQueue=[]; g.warnings=[]; g.zombies=[]; g.waveEndTimer=999;
  snap('cleared');
  g.player.weaponIndex=0;
  const wp=g.player.weapons[0];
  wp.mag=2; wp.reserve=Infinity; wp.reloading=false; wp.cooldown=0;
  g.player.startReload();
  snap('reload started');
  __ZO__.step(0.5);
  snap('after .5');
  __ZO__.step(0.7);
  snap('after 1.2');
  g.player.invuln=0; g.player.shield=0; g.player.hp=100; g.player.maxHp=100;
  const ret = g.player.takeDamage(20, g.player.x+20, g.player.y);
  snap('after damage ' + ret);
  return out;
});
console.log(JSON.stringify(res, null, 2));
await browser.close();

