import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/tmp/zo-shots', { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => { errors.push('pageerror: ' + e.message); console.log('PAGE ERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push('console: ' + m.text()); console.log('CONSOLE ERROR:', m.text()); } });
let passed = 0, failed = 0;
const check = (name, ok, extra = '') => {
  if (ok) { passed++; console.log('  PASS', name); }
  else { failed++; console.log('  FAIL', name, extra); }
};
const section = (name) => console.log('\n## ' + name);

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__ZO__?.ready, null, { timeout: 15000 });

section('Menu help and sound controls');
await page.click('#btn-how');
check('how-to-play opens from menu', await page.locator('#howto').evaluate((el) => el.classList.contains('active')));
await page.screenshot({ path: '/tmp/zo-shots/20-howto.png' });
await page.click('#btn-how-close');
check('how-to-play closes', await page.locator('#howto').evaluate((el) => !el.classList.contains('active')));
const soundBefore = await page.locator('#menu-mute').textContent();
await page.click('#menu-mute');
const soundAfter = await page.locator('#menu-mute').textContent();
check('menu sound toggle changes label', soundBefore !== soundAfter, `${soundBefore} -> ${soundAfter}`);
await page.click('#menu-mute');

section('How-to deploy button');
await page.click('#btn-how');
await page.click('#btn-how-play');
await page.waitForTimeout(250);
check('deploy from help starts game', await page.evaluate(() => __ZO__.snapshot().mode === 'playing'));
check('help overlay dismissed on deploy', await page.locator('#howto').evaluate((el) => !el.classList.contains('active')));

section('Pause buttons and keyboard');
await page.click('#btn-pause');
check('HUD pause button pauses', await page.evaluate(() => __ZO__.snapshot().mode === 'paused'));
check('pause overlay active', await page.locator('#pause').evaluate((el) => el.classList.contains('active')));
const pauseStats = await page.evaluate(() => ({
  wave: document.querySelector('#pause-wave').textContent,
  kills: document.querySelector('#pause-kills').textContent,
  coins: document.querySelector('#pause-coins').textContent,
}));
check('pause stats render', pauseStats.wave === '1' && pauseStats.kills !== '' && pauseStats.coins !== '', JSON.stringify(pauseStats));
await page.screenshot({ path: '/tmp/zo-shots/21-pause.png' });
await page.keyboard.press('Escape');
await page.waitForTimeout(100);
check('Escape resumes play', await page.evaluate(() => __ZO__.snapshot().mode === 'playing'));

section('Intermission and upgrade clicks');
await page.evaluate(() => { __ZO__.addCoins(900); __ZO__.forceIntermission(); __ZO__.step(0.2); });
check('intermission opens after wave clear', await page.evaluate(() => __ZO__.snapshot().mode === 'intermission'));
check('upgrade overlay is active', await page.locator('#upgrade').evaluate((el) => el.classList.contains('active')));
check('three upgrade cards render', await page.locator('.upgrade-card').count() === 3);
const firstId = await page.evaluate(() => __ZO__.snapshot().offers[0].id);
const coinsBeforeBuy = await page.evaluate(() => __ZO__.snapshot().coins);
await page.locator('.upgrade-card').first().click();
await page.waitForTimeout(100);
const afterBuy = await page.evaluate(() => ({ ...__ZO__.snapshot(), firstId: __ZO__.snapshot().offers[0].id }));
check('clicking an upgrade card installs it', (afterBuy.upgrades[firstId] || 0) === 1, JSON.stringify(afterBuy));
check('clicking an upgrade card spends coins', afterBuy.coins < coinsBeforeBuy, JSON.stringify(afterBuy));
check('next wave button enabled', await page.locator('#btn-next-wave').isEnabled());
await page.screenshot({ path: '/tmp/zo-shots/22-upgrade.png' });
await page.click('#btn-next-wave');
await page.waitForTimeout(200);
const wave2 = await page.evaluate(() => __ZO__.snapshot());
check('Next Wave button starts next wave', wave2.mode === 'playing' && wave2.wave === 2, JSON.stringify(wave2));
check('upgrade overlay closes on next wave', await page.locator('#upgrade').evaluate((el) => !el.classList.contains('active')));

section('Pause restart and abandon buttons');
await page.evaluate(() => __ZO__.addCoins(50));
await page.click('#btn-pause');
await page.click('#btn-pause-restart');
await page.waitForTimeout(250);
const restarted = await page.evaluate(() => __ZO__.snapshot());
check('pause restart resets run', restarted.mode === 'playing' && restarted.wave === 1 && restarted.coins === 0, JSON.stringify(restarted));
await page.click('#btn-pause');
await page.click('#btn-pause-menu');
await page.waitForTimeout(200);
check('pause abandon returns to menu', await page.evaluate(() => __ZO__.snapshot().mode === 'menu'));
check('menu overlay restored', await page.locator('#menu').evaluate((el) => el.classList.contains('active')));
check('HUD hidden on abandon', await page.locator('#hud').evaluate((el) => el.classList.contains('hidden')));

section('Game over menu button');
await page.click('#btn-play');
await page.waitForTimeout(200);
await page.evaluate(() => __ZO__.damagePlayer(9999));
await page.waitForTimeout(800);
check('game over overlay active before menu click', await page.locator('#gameover').evaluate((el) => el.classList.contains('active')));
await page.click('#btn-gameover-menu');
await page.waitForTimeout(200);
check('game over main menu works', await page.evaluate(() => __ZO__.snapshot().mode === 'menu'));

section('Mobile help, pause and upgrade layout');
const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const mp = await mctx.newPage();
mp.on('pageerror', (e) => { errors.push('mobile pageerror: ' + e.message); console.log('MOBILE PAGE ERROR:', e.message); });
await mp.goto('http://localhost:3002/', { waitUntil: 'load' });
await mp.waitForFunction(() => window.__ZO__?.ready, null, { timeout: 15000 });
await mp.click('#btn-how');
check('mobile how-to overlay opens', await mp.locator('#howto').evaluate((el) => el.classList.contains('active')));
const howBox = await mp.locator('#howto .modal-panel').boundingBox();
check('mobile how-to fits viewport', howBox.y >= 0 && howBox.y + howBox.height <= 844, JSON.stringify(howBox));
await mp.screenshot({ path: '/tmp/zo-shots/23-mobile-howto.png' });
await mp.click('#btn-how-close');
await mp.click('#btn-play');
await mp.waitForTimeout(300);
await mp.click('#btn-pause');
check('mobile pause overlay opens', await mp.locator('#pause').evaluate((el) => el.classList.contains('active')));
await mp.screenshot({ path: '/tmp/zo-shots/24-mobile-pause.png' });
await mp.click('#btn-resume');
await mp.waitForTimeout(100);
await mp.evaluate(() => { __ZO__.addCoins(900); __ZO__.forceIntermission(); __ZO__.step(0.2); });
check('mobile intermission opens', await mp.evaluate(() => __ZO__.snapshot().mode === 'intermission'));
const upBox = await mp.locator('#upgrade .upgrade-panel').boundingBox();
check('mobile upgrade panel fits viewport', upBox.y >= 0 && upBox.y + upBox.height <= 844, JSON.stringify(upBox));
await mp.screenshot({ path: '/tmp/zo-shots/25-mobile-upgrade.png' });
await mp.locator('.upgrade-card').first().click();
await mp.click('#btn-next-wave');
await mp.waitForTimeout(200);
check('mobile next wave works', await mp.evaluate(() => __ZO__.snapshot().mode === 'playing'));

section('Mobile landscape geometry');
await mp.setViewportSize({ width: 844, height: 390 });
await mp.waitForTimeout(300);
await mp.screenshot({ path: '/tmp/zo-shots/26-mobile-landscape.png' });
const landscape = await mp.evaluate(() => {
  const r = (sel) => {
    const b = document.querySelector(sel).getBoundingClientRect();
    return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), bottom: Math.round(b.bottom), right: Math.round(b.right) };
  };
  return {
    vw: innerWidth, vh: innerHeight,
    health: r('.health-panel'), wave: r('.wave-pill'), right: r('.hud-right'),
    weapons: r('.weapon-list'), move: r('[data-stick="move"]'), aim: r('[data-stick="aim"]'),
  };
});
const overlaps = (a, b) => !(a.right <= b.x || b.right <= a.x || a.bottom <= b.y || b.bottom <= a.y);
check('landscape HUD does not overlap itself', !overlaps(landscape.health, landscape.wave) && !overlaps(landscape.wave, landscape.right), JSON.stringify(landscape));
check('landscape weapon cards fit viewport', landscape.weapons.x >= 0 && landscape.weapons.right <= 844, JSON.stringify(landscape));
check('landscape joysticks fit viewport', landscape.move.x >= 0 && landscape.aim.right <= 844 && landscape.move.bottom <= 390 && landscape.aim.bottom <= 390, JSON.stringify(landscape));

console.log('\n========================================');
console.log(`RESULT: ${passed} passed, ${failed} failed`);
console.log('Errors:', errors.length ? errors : 'none');
await browser.close();
process.exit(failed ? 1 : 0);

